(* ========================================================================= *)
(* Apery's theorem: the irrationality of zeta(3).                            *)
(*                                                                           *)
(* The proof follows John Harrison's HOL Light development apart from the    *)
(* recurrence for bb. The order-4 recurrence and its telescoping certificate *)
(* originate in Bruno Salvy's Maple/Algolib worksheet. They were later       *)
(* formally checked by Chyzak, Mahboubi, Sibut-Pinote and Tassi. The exact   *)
(* operators and contiguity data used here are translated from the later     *)
(* Coq development by Mahboubi and Sibut-Pinote.                             *)
(*                                                                           *)
(* Thus the recurrence data were generated in Maple by creative telescoping, *)
(* using algorithms derived from Zeilberger's work, not generated by Coq.    *)
(* Both Coq and HOL check the data a posteriori. Here P_flat is factored     *)
(* through the order-2 Apery operator. The interior telescoping              *)
(* identity is checked by triangular rational reduction to three factorized  *)
(* polynomial identities. Only the boundary step retains a large cofactor    *)
(* certificate generated offline for this HOL development.                   *)
(*                                                                           *)
(* References:                                                               *)
(*   C. Schneider, "Apery's Double Sum is Plain Sailing Indeed" (2007):      *)
(*   http://www.risc.jku.at/publications/download/risc_3027/Apery.pdf        *)
(*   B. Salvy, "An Algolib-aided version of Apery's proof of the             *)
(*   irrationality of zeta(3)" (2003):                                       *)
(*   http://algo.inria.fr/libraries/autocomb/Apery2-html/apery.html          *)
(*   F. Chyzak, A. Mahboubi, T. Sibut-Pinote and E. Tassi, "A                *)
(*   Computer-Algebra-Based Formal Proof of the Irrationality of zeta(3)"    *)
(*   (2014), doi:10.1007/978-3-319-08970-6_11.                               *)
(*   A. Mahboubi and T. Sibut-Pinote, "A Formal Proof of the                 *)
(*   Irrationality of zeta(3)" (2021), doi:10.23638/LMCS-17(1:16)2021;       *)
(*   https://github.com/rocq-community/apery                                 *)
(* ========================================================================= *)

needs "100/pnt.ml";;

(* ------------------------------------------------------------------------- *)
(* LCMs over sets.                                                           *)
(* ------------------------------------------------------------------------- *)

let LCM_DEF = define
 `LCM (s:num->bool) = iterate(\m n. lcm(m,n)) s I`;;

let LCM_CLAUSES = prove
 (`(LCM {} = 1) /\
   (!x s. FINITE s
          ==> LCM (x INSERT s) = if x IN s then LCM s else lcm(x,LCM s))`,
  ASM_SIMP_TAC[LCM_DEF; MONOIDAL_LCM; ITERATE_CLAUSES; I_THM; NEUTRAL_LCM]);;

let LCM_CLAUSES_NUMSEG = prove
 (`(!m. LCM(m..0) = if m = 0 then 0 else 1) /\
   (!m n. LCM(m..SUC n) =
          if m <= SUC n then lcm(LCM(m..n),SUC n) else 1)`,
  REWRITE_TAC[NUMSEG_CLAUSES] THEN REPEAT STRIP_TAC THEN
  COND_CASES_TAC THEN
  ASM_SIMP_TAC[LCM_CLAUSES; FINITE_NUMSEG; IN_NUMSEG; FINITE_EMPTY] THEN
  REWRITE_TAC[ARITH_RULE `~(SUC n <= n)`; LCM_1; NOT_IN_EMPTY] THEN
  REWRITE_TAC[LCM_SYM] THEN
  MATCH_MP_TAC(MESON[LCM_CLAUSES] `s = {} ==> LCM s = 1`) THEN
  REWRITE_TAC[NUMSEG_EMPTY] THEN ASM_ARITH_TAC);;

let LCM_EQ_0 = prove
 (`!s. FINITE s ==> (LCM s = 0 <=> 0 IN s)`,
  SIMP_TAC[LCM_DEF; ITERATE_LCM_EQ_0; I_THM] THEN SET_TAC[]);;

let LCM_NONZERO = prove
 (`!n. ~(LCM(1..n) = 0)`,
  SIMP_TAC[LCM_EQ_0; FINITE_NUMSEG; IN_NUMSEG; ARITH]);;

let DIVIDES_LCM_SET = prove
 (`!s n. FINITE s /\ n IN s ==> n divides LCM s`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[LCM_DEF] THEN
  MP_TAC(ISPECL [`I:num->num`; `s:num->bool`; `n:num`]
    DIVIDES_ITERATE_LCM) THEN
  ASM_REWRITE_TAC[I_THM]);;

let DIVIDES_LCM_NUMSEG = prove
 (`!m n. 1 <= m /\ m <= n ==> m divides LCM(1..n)`,
  REPEAT STRIP_TAC THEN MATCH_MP_TAC DIVIDES_LCM_SET THEN
  ASM_SIMP_TAC[IN_NUMSEG; FINITE_NUMSEG; LE_1]);;

let PRIMEPOW_DIVIDES_SET_LCM = prove
 (`!s p k. FINITE s /\ prime p
           ==> (p EXP k divides LCM(s) <=>
                s = {} /\ k = 0 \/ ?n. n IN s /\ p EXP k divides n)`,
  REPEAT STRIP_TAC THEN
  ASM_SIMP_TAC[LCM_DEF; PRIMEPOW_DIVIDES_ITERATE_LCM; I_THM] THEN
  ASM_CASES_TAC `s:num->bool = {}` THEN ASM_REWRITE_TAC[NOT_IN_EMPTY] THEN
  ASM_MESON_TAC[MEMBER_NOT_EMPTY; EXP; DIVIDES_1]);;

let PRIMEPOW_DIVIDES_NUMSEG_LCM = prove
 (`!n p k. prime p
           ==> (p EXP k divides LCM(1..n) <=> n = 0 /\ k = 0 \/
                ?m. 1 <= m /\ m <= n /\ p EXP k divides m)`,
  SIMP_TAC[PRIMEPOW_DIVIDES_SET_LCM; FINITE_NUMSEG] THEN
  REWRITE_TAC[NUMSEG_EMPTY; ARITH_RULE `n < 1 <=> n = 0`] THEN
  REWRITE_TAC[IN_NUMSEG; GSYM CONJ_ASSOC]);;


let PRIMEPOW_DIVIDES_NUMSEG_LCM_SIMPLE = prove
 (`!n p k. prime p
           ==> (p EXP k divides LCM(1..n) <=> n = 0 /\ k = 0 \/ p EXP k <= n)`,
  REPEAT STRIP_TAC THEN ASM_SIMP_TAC[PRIMEPOW_DIVIDES_NUMSEG_LCM] THEN
  AP_TERM_TAC THEN EQ_TAC THENL
   [DISCH_THEN(X_CHOOSE_THEN `m:num` STRIP_ASSUME_TAC) THEN
    FIRST_ASSUM(MP_TAC o MATCH_MP DIVIDES_LE) THEN
    ASM_MESON_TAC[LE_TRANS; LE_1];
    DISCH_TAC THEN EXISTS_TAC `p EXP k` THEN ASM_REWRITE_TAC[DIVIDES_REFL] THEN
    ASM_SIMP_TAC[ARITH_RULE `1 <= p <=> ~(p = 0)`; PRIME_IMP_NZ; EXP_EQ_0]]);;

let BINOM_MULTIPLE_DIVIDES_LCM = prove
 (`!m. 1 <= m /\ m <= n ==> (m * binom(n,m)) divides LCM(1..n)`,
  REPEAT STRIP_TAC THEN MATCH_MP_TAC DIVIDES_CMUL2 THEN
  EXISTS_TAC `FACT m * FACT(n - m)` THEN
  MP_TAC(SPECL [`n - m:num`; `m:num`] BINOM_FACT) THEN
  ASM_SIMP_TAC[MULT_EQ_0; FACT_NZ; SUB_ADD] THEN
  SIMP_TAC[ARITH_RULE `(m * k) * x * b:num = x * k * m * b`] THEN
  DISCH_TAC THEN REWRITE_TAC[GSYM MULT_ASSOC] THEN
  ONCE_REWRITE_TAC[PRIMEPOW_DIVISORS_DIVIDES] THEN
  REWRITE_TAC[IMP_CONJ; RIGHT_FORALL_IMP_THM] THEN
  X_GEN_TAC `p:num` THEN DISCH_TAC THEN
  SUBGOAL_THEN `~(p = 0) /\ ~(p = 1) /\ 2 <= p /\ ~(p <= 1)`
  STRIP_ASSUME_TAC THENL
   [FIRST_ASSUM(MP_TAC o MATCH_MP PRIME_GE_2) THEN ARITH_TAC; ALL_TAC] THEN
  ASM_SIMP_TAC[PRIMEPOW_DIVIDES_INDEX; MULT_EQ_0; FACT_NZ;
               INDEX_FACT_UNBOUNDED; LE_1; LCM_NONZERO; INDEX_MUL] THEN
  MATCH_MP_TAC(ARITH_RULE `a:num <= b ==> !k. k <= a ==> k <= b`) THEN
  ASM_SIMP_TAC[index_def; LE_1; LCM_NONZERO] THEN
  ONCE_REWRITE_TAC[ARITH_RULE `CARD s = CARD s * 1`] THEN
  ASM_SIMP_TAC[GSYM NSUM_CONST; FINITE_INDICES; LE_1; LCM_NONZERO] THEN
  ONCE_REWRITE_TAC[SET_RULE
   `{x | P x /\ Q x} = {x | x IN {x | P x} /\ Q x}`] THEN
  REWRITE_TAC[NSUM_RESTRICT_SET] THEN
  REPLICATE_TAC 2
   (ASM_SIMP_TAC[CONV_RULE(RAND_CONV SYM_CONV) (SPEC_ALL NSUM_ADD_GEN);
                 IN_ELIM_THM; DIV_EQ_0; EXP_EQ_0;
                 NOT_LT; FINITE_EXP_LE; FINITE_INDICES; LCM_NONZERO;
                 MESON[ARITH] `((if p then 1 else 0) = 0) <=> ~p`;
                 ADD_EQ_0; DE_MORGAN_THM; FINITE_UNION; LE_1;
                 SET_RULE `{x | P x /\ (Q x \/ R x)} =
                           {x | P x /\ Q x} UNION {x | P x /\ R x}`] THEN
    TRY(MATCH_MP_TAC NSUM_LE_GEN)) THEN
  X_GEN_TAC `j:num` THEN DISCH_TAC THEN
  ASM_SIMP_TAC[PRIMEPOW_DIVIDES_NUMSEG_LCM_SIMPLE] THEN
  ASM_CASES_TAC `p EXP j divides m` THEN ASM_REWRITE_TAC[] THENL
   [COND_CASES_TAC THENL
     [ALL_TAC; ASM_MESON_TAC[DIVIDES_LE; LE_TRANS; LE_1]] THEN
    REWRITE_TAC[ARITH_RULE `1 + a <= b + c + 1 <=> a <= b + c`] THEN
    ASM_SIMP_TAC[LE_LDIV_EQ; EXP_EQ_0; PRIME_IMP_NZ] THEN
    RULE_ASSUM_TAC(REWRITE_RULE[DIVIDES_DIV_MULT]) THEN
    ASM_SIMP_TAC[ARITH_RULE `p * ((d + e) + 1):num = d * p + e * p + p`] THEN
    MATCH_MP_TAC(ARITH_RULE `m:num <= n /\ n - m < p ==> n < m + p`) THEN
    ASM_REWRITE_TAC[] THEN MP_TAC(SPECL [`n - m:num`; `p EXP j`] DIVISION) THEN
    ASM_SIMP_TAC[EXP_EQ_0; PRIME_IMP_NZ] THEN ASM_ARITH_TAC;
    REWRITE_TAC[ADD_CLAUSES] THEN
    COND_CASES_TAC THEN ASM_SIMP_TAC[GSYM NOT_LE; DIV_LT; LE_0] THEN
    ASM_SIMP_TAC[LE_LDIV_EQ; EXP_EQ_0; PRIME_IMP_NZ] THEN
    MATCH_MP_TAC(ARITH_RULE
     `!m:num. m <= n /\ m + (n - m) < x ==> n < x`) THEN
    EXISTS_TAC `m:num` THEN ASM_REWRITE_TAC[] THEN
    MP_TAC(SPECL [`n - m:num`; `p EXP j`] DIVISION) THEN
    MP_TAC(SPECL [`m:num`; `p EXP j`] DIVISION) THEN
    ASM_SIMP_TAC[EXP_EQ_0; PRIME_IMP_NZ] THEN ASM_ARITH_TAC]);;

(* ------------------------------------------------------------------------- *)
(* The real zeta function.                                                   *)
(* ------------------------------------------------------------------------- *)

let ZETA = new_definition
 `ZETA x = Re(zeta(Cx x))`;;

(* ------------------------------------------------------------------------- *)
(* The key sequences.                                                        *)
(* ------------------------------------------------------------------------- *)

let cc = new_definition
 `cc n k = &(binom(n + k,k)) pow 2 * &(binom(n,k)) pow 2`;;

let zz = new_definition
 `zz n = sum(1..n) (\k. &1 / &k pow 3)`;;

let aa = new_definition
 `aa n = sum(0..n) (\k. cc n k)`;;

let bb = new_definition
 `bb n = aa n * zz n +
         sum (1..n)
             (\k. sum (1..k)
                      (\m. --(&1) pow (m + 1) /
                           (&2 * &m pow 3 * &(binom(n,m)) * &(binom(n+m,m))) *
                           cc n k))`;;

(* ------------------------------------------------------------------------- *)
(* Cosmetically different form for b from Schneider's paper.                 *)
(* ------------------------------------------------------------------------- *)

let BB_ALT = prove
 (`!n. bb n =
       sum (0..n)
           (\k. &(binom(n + k,k)) pow 2 * &(binom(n,k)) pow 2 *
                (zz n +
                 sum (1..k)
                     (\m. --(&1) pow (m - 1) /
                           (&2 * &m pow 3 *
                            &(binom(n+m,m)) * &(binom(n,m))))))`,
  GEN_TAC THEN REWRITE_TAC[REAL_ADD_LDISTRIB; SUM_ADD_NUMSEG] THEN
  REWRITE_TAC[bb; aa; cc; GSYM SUM_RMUL; REAL_POW_MUL] THEN
  REWRITE_TAC[GSYM REAL_MUL_ASSOC] THEN AP_TERM_TAC THEN
  SIMP_TAC[ISPECL [`f:num->real`; `0`; `n:num`] SUM_CLAUSES_LEFT; LE_0] THEN
  REWRITE_TAC[SUM_CLAUSES_NUMSEG; ARITH_EQ; REAL_MUL_RZERO; REAL_ADD_LID] THEN
  REWRITE_TAC[ADD_CLAUSES] THEN MATCH_MP_TAC SUM_EQ_NUMSEG THEN
  X_GEN_TAC `k:num` THEN STRIP_TAC THEN REWRITE_TAC[GSYM SUM_LMUL] THEN
  MATCH_MP_TAC SUM_EQ_NUMSEG THEN X_GEN_TAC `m:num` THEN STRIP_TAC THEN
  REWRITE_TAC[] THEN
  ASM_SIMP_TAC[ARITH_RULE `1 <= m ==> m + 1 = SUC(SUC(m - 1))`] THEN
  REWRITE_TAC[real_pow; REAL_MUL_LNEG; REAL_MUL_LID; REAL_MUL_RNEG] THEN
  REWRITE_TAC[REAL_NEG_NEG; REAL_MUL_AC]);;

(* ========================================================================= *)
(* *** Part 0: estimation of LCM(1..n)                                       *)
(* ========================================================================= *)

let DIVIDES_NPRODUCT_FROM_MEMBER = prove
 (`!s n x:A. FINITE s /\ n divides (f x) /\ x IN s
             ==> n divides nproduct s f`,
  REWRITE_TAC[IMP_CONJ; RIGHT_FORALL_IMP_THM] THEN
  MATCH_MP_TAC FINITE_INDUCT_STRONG THEN REWRITE_TAC[NOT_IN_EMPTY] THEN
  SIMP_TAC[IN_INSERT; NPRODUCT_CLAUSES] THEN
  MESON_TAC[DIVIDES_LMUL; DIVIDES_RMUL]);;

let LOG_LCM_BOUND = prove
 (`!n. ~(n = 0)
       ==> log(&(LCM(1..n))) <= log(&n) * &(CARD {p | prime p /\ p <= n})`,
  REPEAT STRIP_TAC THEN
  ASM_SIMP_TAC[LCM_CLAUSES_NUMSEG; ARITH; LOG_1; REAL_ADD_LID; REAL_POS] THEN
  ABBREV_TAC `a = \p. @k. floor(log(&n) / log(&p)) = &k` THEN
  SUBGOAL_THEN `!p. prime p ==> floor(log(&n) / log(&p)) = &(a p)`
  ASSUME_TAC THENL
   [REPEAT STRIP_TAC THEN EXPAND_TAC "a" THEN CONV_TAC SELECT_CONV THEN
    MATCH_MP_TAC FLOOR_POS THEN MATCH_MP_TAC REAL_LE_DIV THEN
    ASM_SIMP_TAC[LOG_POS; LE_1; PRIME_IMP_NZ; REAL_OF_NUM_LE];
    ALL_TAC] THEN
  TRANS_TAC REAL_LE_TRANS
   `log(&(nproduct {p | p IN 1..n /\ prime p} (\p. p EXP (a p))))` THEN
  CONJ_TAC THENL
   [MATCH_MP_TAC LOG_MONO_LE_IMP THEN
    ASM_SIMP_TAC[REAL_OF_NUM_LT; LCM_NONZERO; LE_1; REAL_OF_NUM_LE] THEN
    MATCH_MP_TAC(MESON[DIVIDES_LE] `~(n = 0) /\ m divides n ==> m <= n`) THEN
    CONJ_TAC THENL
     [SIMP_TAC[NPRODUCT_EQ_0; FINITE_NUMSEG; FINITE_RESTRICT] THEN
      REWRITE_TAC[IN_ELIM_THM; EXP_EQ_0] THEN MESON_TAC[PRIME_IMP_NZ];
      ALL_TAC] THEN
    ONCE_REWRITE_TAC[PRIMEPOW_DIVISORS_DIVIDES] THEN
    ASM_SIMP_TAC[IMP_CONJ; PRIMEPOW_DIVIDES_NUMSEG_LCM] THEN
    REWRITE_TAC[LEFT_IMP_EXISTS_THM] THEN REPEAT STRIP_TAC THEN
    ASM_CASES_TAC `k = 0` THEN ASM_REWRITE_TAC[EXP; DIVIDES_1] THEN
    MATCH_MP_TAC DIVIDES_NPRODUCT_FROM_MEMBER THEN EXISTS_TAC `p:num` THEN
    ASM_SIMP_TAC[IN_ELIM_THM; FINITE_RESTRICT; FINITE_NUMSEG; IN_NUMSEG] THEN
    ASM_SIMP_TAC[PRIME_GE_2; DIVIDES_EXP_LE; ARITH_RULE
     `2 <= p ==> 1 <= p`] THEN
    MATCH_MP_TAC(TAUT `b /\ (b ==> a) ==> a /\ b`) THEN CONJ_TAC THENL
     [SUBGOAL_THEN `p divides m` MP_TAC THENL
       [TRANS_TAC DIVIDES_TRANS `p EXP k` THEN ASM_REWRITE_TAC[] THEN
        GEN_REWRITE_TAC LAND_CONV [GSYM EXP_1] THEN
        ASM_SIMP_TAC[DIVIDES_EXP_LE; PRIME_GE_2; LE_1];
        DISCH_THEN(MP_TAC o MATCH_MP DIVIDES_LE) THEN ASM_ARITH_TAC];
      DISCH_TAC THEN REWRITE_TAC[ARITH_RULE `m <= n <=> m < n + 1`] THEN
      FIRST_X_ASSUM(MP_TAC o MATCH_MP DIVIDES_LE) THEN
      ASM_SIMP_TAC[LE_1] THEN DISCH_TAC THEN
      FIRST_X_ASSUM(MP_TAC o SPEC `p:num`) THEN ASM_REWRITE_TAC[] THEN
      REWRITE_TAC[GSYM REAL_OF_NUM_LT; GSYM REAL_OF_NUM_ADD] THEN
      MATCH_MP_TAC(REAL_ARITH
       `x < floor x + &1 /\ k <= x ==> floor x = a ==> k < a + &1`) THEN
      REWRITE_TAC[FLOOR] THEN
      ASM_SIMP_TAC[REAL_LE_RDIV_EQ; LOG_POS_LT; REAL_OF_NUM_LT; PRIME_GE_2;
                   ARITH_RULE `1 < p <=> 2 <= p`; GSYM LOG_POW;
                   PRIME_IMP_NZ; LE_1] THEN
      MATCH_MP_TAC LOG_MONO_LE_IMP THEN
      ASM_REWRITE_TAC[REAL_OF_NUM_LE; REAL_OF_NUM_LE; REAL_OF_NUM_POW] THEN
      CONJ_TAC THENL [REWRITE_TAC[REAL_OF_NUM_LT]; ASM_ARITH_TAC] THEN
      REWRITE_TAC[EXP_LT_0] THEN ASM_MESON_TAC[PRIME_IMP_NZ]];
    SIMP_TAC[LOG_PRODUCT; LE_1; EXP_EQ_0; PRIME_IMP_NZ; FINITE_RESTRICT;
     REAL_OF_NUM_NPRODUCT; FINITE_NUMSEG; REAL_OF_NUM_LT; FORALL_IN_GSPEC] THEN
    REWRITE_TAC[GSYM REAL_OF_NUM_POW] THEN
    TRANS_TAC REAL_LE_TRANS `sum {p | p IN 1..n /\ prime p} (\p. log(&n))` THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC SUM_LE THEN
      SIMP_TAC[FINITE_RESTRICT; FINITE_NUMSEG; FORALL_IN_GSPEC] THEN
      X_GEN_TAC `p:num` THEN REWRITE_TAC[IN_NUMSEG] THEN STRIP_TAC THEN
      ASM_SIMP_TAC[LOG_POW; REAL_OF_NUM_LT; LE_1] THEN
      ASM_SIMP_TAC[GSYM REAL_LE_RDIV_EQ; LOG_POS_LT; REAL_OF_NUM_LT;
                   PRIME_GE_2; ARITH_RULE `1 < n <=> 2 <= n`] THEN
      FIRST_X_ASSUM(MP_TAC o SPEC `p:num`) THEN ASM_REWRITE_TAC[] THEN
      MESON_TAC[FLOOR];
      ONCE_REWRITE_TAC[REAL_MUL_SYM] THEN
      SIMP_TAC[SUM_CONST; FINITE_RESTRICT; FINITE_NUMSEG] THEN
      MATCH_MP_TAC REAL_EQ_IMP_LE THEN AP_THM_TAC THEN AP_TERM_TAC THEN
      AP_TERM_TAC THEN AP_TERM_TAC THEN
      REWRITE_TAC[EXTENSION; IN_NUMSEG; ARITH_RULE `1 <= n <=> ~(n = 0)`] THEN
      REWRITE_TAC[IN_ELIM_THM] THEN MESON_TAC[PRIME_0]]]);;

let LCM_BOUND = prove
 (`!e. &0 < e
       ==> eventually (\n. &(LCM(1..n)) < exp((&1 + e) * &n)) sequentially`,
  REPEAT STRIP_TAC THEN MP_TAC PNT THEN
  REWRITE_TAC[REALLIM_SEQUENTIALLY; EVENTUALLY_SEQUENTIALLY] THEN
  DISCH_THEN(MP_TAC o SPEC `e:real`) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(X_CHOOSE_TAC `N:num`) THEN EXISTS_TAC `N + 1` THEN
  X_GEN_TAC `n:num` THEN DISCH_TAC THEN
  FIRST_X_ASSUM(MP_TAC o SPEC `n:num`) THEN
  ANTS_TAC THENL [ASM_ARITH_TAC; ALL_TAC] THEN DISCH_TAC THEN
  W(MP_TAC o PART_MATCH (rand o rand) LOG_MONO_LT o snd) THEN
  SIMP_TAC[REAL_EXP_POS_LT; REAL_OF_NUM_LT; LCM_NONZERO; LE_1; LOG_EXP] THEN
  DISCH_THEN(SUBST1_TAC o SYM) THEN
  TRANS_TAC REAL_LET_TRANS `log(&n) * &(CARD {p | prime p /\ p <= n})` THEN
  CONJ_TAC THENL [MATCH_MP_TAC LOG_LCM_BOUND THEN ASM_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `&0 < &n` ASSUME_TAC THENL
   [REWRITE_TAC[REAL_OF_NUM_LT] THEN ASM_ARITH_TAC; ALL_TAC] THEN
  ASM_SIMP_TAC[GSYM REAL_LT_LDIV_EQ] THEN FIRST_X_ASSUM(MATCH_MP_TAC o MATCH_MP
   (REAL_ARITH `abs(x - &1) < e ==> y = x ==> y < &1 + e`)) THEN
  REWRITE_TAC[real_div; REAL_INV_MUL; REAL_INV_INV; REAL_MUL_AC]);;

let LCM_BOUND_SIMPLE = prove
 (`?N. !n. N <= n ==> LCM(1..n) < 3 EXP n`,
  MP_TAC(SPEC `&1 / &16` LCM_BOUND) THEN CONV_TAC REAL_RAT_REDUCE_CONV THEN
  REWRITE_TAC[EVENTUALLY_SEQUENTIALLY] THEN
  MATCH_MP_TAC MONO_EXISTS THEN GEN_TAC THEN
  MATCH_MP_TAC MONO_FORALL THEN GEN_TAC THEN
  MATCH_MP_TAC MONO_IMP THEN REWRITE_TAC[GSYM REAL_OF_NUM_LT] THEN
  MATCH_MP_TAC(REWRITE_RULE[IMP_CONJ_ALT] REAL_LTE_TRANS) THEN
  TRANS_TAC REAL_LE_TRANS `exp(log(&3) * &n)` THEN CONJ_TAC THENL
   [REWRITE_TAC[REAL_EXP_MONO_LE] THEN
    MATCH_MP_TAC REAL_LE_RMUL THEN REWRITE_TAC[REAL_POS] THEN
    ONCE_REWRITE_TAC[GSYM REAL_EXP_MONO_LE] THEN
    SIMP_TAC[EXP_LOG; REAL_OF_NUM_LT; ARITH] THEN
    MP_TAC(ISPECL [`8`; `Cx(&17 / &16)`] TAYLOR_CEXP) THEN
    SIMP_TAC[RE_CX; REAL_ABS_NUM; GSYM CX_EXP; GSYM CX_DIV; GSYM CX_SUB;
             COMPLEX_POW_ONE; COMPLEX_NORM_CX] THEN
    CONV_TAC(ONCE_DEPTH_CONV EXPAND_VSUM_CONV) THEN
    REWRITE_TAC[GSYM CX_ADD; GSYM CX_SUB; GSYM CX_DIV; GSYM CX_POW;
                COMPLEX_NORM_CX] THEN
    CONV_TAC NUM_REDUCE_CONV THEN CONV_TAC REAL_RAT_REDUCE_CONV THEN
    ONCE_REWRITE_TAC[REAL_MUL_SYM] THEN REAL_ARITH_TAC;
    ONCE_REWRITE_TAC[REAL_MUL_SYM] THEN REWRITE_TAC[REAL_EXP_N] THEN
    SIMP_TAC[EXP_LOG; REAL_OF_NUM_LT; ARITH; GSYM REAL_OF_NUM_POW] THEN
    REWRITE_TAC[REAL_LE_REFL]]);;

(* ========================================================================= *)
(* *** Part 1: b^n / a^n ---> zeta(3)                                        *)
(* ========================================================================= *)

let CC_EQ_0 = prove
 (`!n k. cc n k = &0 <=> n + 1 <= k`,
  REWRITE_TAC[cc; BINOM_EQ_0; REAL_ENTIRE; REAL_POW_EQ_0; REAL_OF_NUM_EQ;
              ARITH_EQ] THEN
  ARITH_TAC);;

let CC_POS_LT = prove
 (`!n k. k <= n ==> &0 < cc n k`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[REAL_LT_LE] THEN
  CONV_TAC(ONCE_DEPTH_CONV SYM_CONV) THEN REWRITE_TAC[CC_EQ_0] THEN
  CONJ_TAC THENL [REWRITE_TAC[cc]; ASM_ARITH_TAC] THEN
  SIMP_TAC[REAL_POS; REAL_POW_LE; REAL_LE_MUL]);;

let AA_POS_LT = prove
 (`!n. &0 < aa n`,
  GEN_TAC THEN REWRITE_TAC[aa] THEN MATCH_MP_TAC SUM_POS_LT THEN
  SIMP_TAC[FINITE_NUMSEG; IN_NUMSEG; REAL_LT_IMP_LE; CC_POS_LT] THEN
  EXISTS_TAC `0` THEN SIMP_TAC[LE_0; CC_POS_LT]);;

let AA_NONZERO = prove
 (`!n. ~(aa n = &0)`,
  SIMP_TAC[REAL_LT_IMP_NZ; AA_POS_LT]);;

(* The summand's real part (k >= 1 so the cpow base is nonzero). *)
let RE_SUMMAND = prove
 (`!k. 1 <= k ==> Re(Cx(&1) / Cx(&k) cpow Cx(&3)) = &1 / &k pow 3`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[CPOW_N] THEN
  COND_CASES_TAC THENL
   [FIRST_X_ASSUM(MP_TAC o REWRITE_RULE[CX_INJ; REAL_OF_NUM_EQ]) THEN
    ASM_ARITH_TAC;
    REWRITE_TAC[GSYM CX_POW; GSYM CX_DIV; RE_CX]]);;

(* Take real parts of the complex zeta series at s = 3. *)
let ZZ_SUMS = prove
 (`((\k. &1 / &k pow 3) real_sums ZETA(&3)) (from 1)`,
  MATCH_MP_TAC REAL_SUMS_EQ THEN
  EXISTS_TAC `\k. Re(Cx(&1) / Cx(&k) cpow Cx(&3))` THEN CONJ_TAC THENL
   [SIMP_TAC[IN_FROM; RE_SUMMAND];
    MP_TAC(SPEC `Cx(&3)` ZETA_CONVERGES) THEN
    REWRITE_TAC[REAL_ARITH `&1 < &3`; RE_CX] THEN
    DISCH_THEN(MP_TAC o MATCH_MP REAL_SUMS_RE) THEN
    REWRITE_TAC[ZETA; o_DEF]]);;

let ZZ_LIM = prove
 (`(zz ---> ZETA(&3)) sequentially`,
  SUBGOAL_THEN `zz = \n. sum(from 1 INTER (0..n)) (\k. &1 / &k pow 3)`
  SUBST1_TAC THENL
   [REWRITE_TAC[FUN_EQ_THM; zz; FROM_INTER_NUMSEG];
    MP_TAC ZZ_SUMS THEN REWRITE_TAC[real_sums]]);;

let ZETA3_POS = prove
 (`&0 < ZETA(&3)`,
  MP_TAC(ISPECL [`\n. inv(&n pow 3)`; `from 1`; `{1}`]
   REAL_PARTIAL_SUMS_LE_INFSUM_GEN) THEN
  REWRITE_TAC[FINITE_SING; SING_SUBSET; SUM_SING; IN_FROM] THEN
  REWRITE_TAC[LE_REFL; REAL_LE_INV_EQ; REAL_POS] THEN
  SUBGOAL_THEN `((\n. inv(&n pow 3)) real_sums ZETA(&3)) (from 1)`
  ASSUME_TAC THENL
   [MP_TAC ZZ_LIM THEN
    REWRITE_TAC[real_sums; REWRITE_RULE[GSYM FUN_EQ_THM; ETA_AX] zz;
                FROM_INTER_NUMSEG; real_div; REAL_MUL_LID];
    FIRST_ASSUM(ASSUME_TAC o MATCH_MP REAL_SUMS_SUMMABLE) THEN
    FIRST_ASSUM(ASSUME_TAC o MATCH_MP REAL_INFSUM_UNIQUE) THEN
    ASM_SIMP_TAC[REAL_POW_LE; REAL_POS] THEN ASM_REAL_ARITH_TAC]);;

let BB_OVER_AA_LIM = prove
 (`((\n. bb n / aa n) ---> ZETA(&3)) sequentially`,
  REWRITE_TAC[bb; REAL_ARITH `(a * z + s) / a:real = (a / a) * z + s / a`] THEN
  SIMP_TAC[REAL_DIV_REFL; AA_NONZERO; REAL_MUL_LID] THEN
  GEN_REWRITE_TAC LAND_CONV [GSYM REAL_ADD_RID] THEN
  MATCH_MP_TAC REALLIM_ADD THEN REWRITE_TAC[ZZ_LIM] THEN
  MATCH_MP_TAC REALLIM_NULL_COMPARISON THEN EXISTS_TAC
   `\n. sum(1..n) (\k. sum(1..k) (\m. cc n k / (&2 * &n pow 2))) / aa n` THEN
  CONJ_TAC THENL
   [REWRITE_TAC[EVENTUALLY_SEQUENTIALLY] THEN EXISTS_TAC `1` THEN
    X_GEN_TAC `n:num` THEN DISCH_TAC THEN
    SIMP_TAC[REAL_ABS_DIV; AA_POS_LT; REAL_ARITH `&0 < x ==> abs x = x`;
             REAL_LE_DIV2_EQ] THEN
    MATCH_MP_TAC SUM_ABS_LE THEN REWRITE_TAC[FINITE_NUMSEG; IN_NUMSEG] THEN
    X_GEN_TAC `k:num` THEN STRIP_TAC THEN MATCH_MP_TAC SUM_ABS_LE THEN
    REWRITE_TAC[FINITE_NUMSEG; IN_NUMSEG] THEN X_GEN_TAC `m:num` THEN
    STRIP_TAC THEN
    REWRITE_TAC[real_div; REAL_ABS_MUL; REAL_ABS_POW; REAL_ABS_NEG;
                REAL_ABS_NUM; REAL_POW_ONE; REAL_MUL_LID] THEN
    ASM_SIMP_TAC[CC_POS_LT; REAL_ARITH `&0 < x ==> abs x = x`] THEN
    GEN_REWRITE_TAC RAND_CONV [REAL_MUL_SYM] THEN
    ASM_SIMP_TAC[REAL_LE_RMUL_EQ; CC_POS_LT; REAL_ABS_INV] THEN
    MATCH_MP_TAC REAL_LE_INV2 THEN
    ASM_SIMP_TAC[REAL_LT_MUL; REAL_POW_LT; REAL_OF_NUM_LT; LE_1; ARITH] THEN
    REWRITE_TAC[REAL_ABS_MUL; REAL_ABS_POW; REAL_ABS_NUM] THEN
    MATCH_MP_TAC REAL_LE_LMUL THEN REWRITE_TAC[REAL_POS] THEN
    REWRITE_TAC[REAL_OF_NUM_POW; REAL_OF_NUM_MUL; REAL_OF_NUM_LE] THEN
    ASM_CASES_TAC `m:num = n` THENL
     [REWRITE_TAC[ARITH_RULE
       `n <= m EXP 3 * x <=> n * 1 <= m EXP 2 * m * x`] THEN
      ASM_REWRITE_TAC[LE_MULT_LCANCEL] THEN DISJ2_TAC THEN
      REWRITE_TAC[ARITH_RULE `1 <= n <=> ~(n = 0)`; MULT_EQ_0] THEN
      REWRITE_TAC[BINOM_EQ_0] THEN ASM_ARITH_TAC;
      MATCH_MP_TAC(ARITH_RULE
       `n * n <= b * c /\ 1 * b * c <= m * b * c
        ==> n EXP 2 <= m * b * c`) THEN
      REWRITE_TAC[LE_MULT_RCANCEL; ARITH_RULE `1 <= n <=> ~(n = 0)`] THEN
      ASM_SIMP_TAC[EXP_EQ_0; LE_1] THEN MATCH_MP_TAC LE_MULT2 THEN
      MATCH_MP_TAC(ARITH_RULE
       `n <= binom(n,m) /\ n + m <= binom(n + m,m)
        ==> n <= binom(n,m) /\ n <= binom(n + m,m)`) THEN
      CONJ_TAC THEN MATCH_MP_TAC BINOM_GE_TOP THEN ASM_ARITH_TAC];
    ALL_TAC] THEN
  MATCH_MP_TAC REALLIM_NULL_COMPARISON THEN EXISTS_TAC
   `\n. sum(1..n) (\k. &k * cc n k / (&2 * &n pow 2)) / aa n` THEN
  CONJ_TAC THENL
   [REWRITE_TAC[EVENTUALLY_SEQUENTIALLY] THEN EXISTS_TAC `1` THEN
    X_GEN_TAC `n:num` THEN DISCH_TAC THEN
    REWRITE_TAC[real_div; SUM_RMUL; REAL_ABS_MUL; REAL_ABS_INV;
                REAL_ABS_POW; REAL_ABS_NUM; REAL_MUL_ASSOC] THEN
    SIMP_TAC[AA_POS_LT; REAL_ARITH `&0 < x ==> abs x = x`] THEN
    ASM_SIMP_TAC[GSYM real_div;  REAL_LE_DIV2_EQ;  REAL_POW_LT;
                 REAL_ARITH `&0 < &2 * x <=> &0 < x`;
                 REAL_OF_NUM_LT; AA_POS_LT; LE_1; ARITH] THEN
    SIMP_TAC[SUM_CONST; CARD_NUMSEG_1; FINITE_NUMSEG] THEN
    MATCH_MP_TAC(REAL_ARITH `&0 <= x ==> abs x <= x`) THEN
    MATCH_MP_TAC SUM_POS_LE_NUMSEG THEN REPEAT STRIP_TAC THEN
    REWRITE_TAC[] THEN MATCH_MP_TAC REAL_LE_MUL THEN
    ASM_SIMP_TAC[CC_POS_LT; REAL_LT_IMP_LE; REAL_POS];
    ALL_TAC] THEN
  MATCH_MP_TAC REALLIM_NULL_COMPARISON THEN
  EXISTS_TAC `\n. inv(&2) * inv(&n)` THEN
  SIMP_TAC[REALLIM_1_OVER_N; REALLIM_NULL_LMUL] THEN
  REWRITE_TAC[EVENTUALLY_SEQUENTIALLY] THEN EXISTS_TAC `1` THEN
  X_GEN_TAC `n:num` THEN DISCH_TAC THEN REWRITE_TAC[REAL_ABS_DIV] THEN
  SIMP_TAC[AA_POS_LT; REAL_ARITH `&0 < x ==> abs x = x`; REAL_LE_LDIV_EQ] THEN
  REWRITE_TAC[real_div; REAL_MUL_ASSOC; SUM_RMUL; REAL_ABS_MUL] THEN
  REWRITE_TAC[REAL_ABS_INV; REAL_ABS_MUL; REAL_ABS_POW; REAL_ABS_NUM] THEN
  ASM_SIMP_TAC[GSYM real_div;  REAL_LE_LDIV_EQ; REAL_POW_LT;
               REAL_ARITH `&0 < &2 * x <=> &0 < x`; REAL_OF_NUM_LT; LE_1] THEN
  ASM_SIMP_TAC[LE_1; REAL_OF_NUM_LT; REAL_FIELD
   `&0 < x ==> (inv(&2) / x * a) * &2 * x pow 2 = x * a`] THEN
  TRANS_TAC REAL_LE_TRANS `sum(1..n) (\k. &n * cc n k)` THEN CONJ_TAC THENL
   [MATCH_MP_TAC SUM_ABS_LE THEN
    SIMP_TAC[FINITE_NUMSEG; REAL_LE_RMUL_EQ; CC_POS_LT; REAL_ABS_MUL;
             REAL_ARITH `&0 < x ==> abs x = x`; IN_NUMSEG; REAL_ABS_NUM;
             REAL_OF_NUM_LE];
    REWRITE_TAC[SUM_LMUL] THEN MATCH_MP_TAC REAL_LE_LMUL THEN
    REWRITE_TAC[REAL_POS; aa] THEN MATCH_MP_TAC SUM_SUBSET_SIMPLE THEN
    SIMP_TAC[IN_NUMSEG; IN_DIFF; FINITE_NUMSEG; REAL_LT_IMP_LE; CC_POS_LT] THEN
    REWRITE_TAC[SUBSET; IN_NUMSEG] THEN ARITH_TAC]);;

(* ========================================================================= *)
(* *** Part 2: integer nature of a_n and scaled b_n.                         *)
(* ========================================================================= *)

let AA_INTEGER = prove
 (`!n. integer(aa n)`,
  GEN_TAC THEN REWRITE_TAC[aa; cc] THEN
  MATCH_MP_TAC INTEGER_SUM THEN SIMP_TAC[INTEGER_CLOSED]);;

let BB_INTEGER = prove
 (`!n. integer(&2 * &(LCM(1..n)) pow 3 * bb n)`,
  GEN_TAC THEN REWRITE_TAC[bb; REAL_ADD_LDISTRIB; GSYM SUM_LMUL] THEN
  MATCH_MP_TAC INTEGER_ADD THEN CONJ_TAC THENL
   [MATCH_MP_TAC INTEGER_MUL THEN REWRITE_TAC[INTEGER_CLOSED] THEN
    ONCE_REWRITE_TAC[REAL_ARITH `a * b * c:real = b * a * c`] THEN
    MATCH_MP_TAC INTEGER_MUL THEN REWRITE_TAC[AA_INTEGER] THEN
    REWRITE_TAC[zz; GSYM SUM_LMUL] THEN MATCH_MP_TAC INTEGER_SUM THEN
    X_GEN_TAC `k:num` THEN REWRITE_TAC[IN_NUMSEG] THEN STRIP_TAC THEN
    REWRITE_TAC[real_div; REAL_MUL_LID; REAL_OF_NUM_POW] THEN
    REWRITE_TAC[GSYM real_div; INTEGER_DIV] THEN DISJ2_TAC THEN
    MATCH_MP_TAC DIVIDES_EXP THEN ASM_SIMP_TAC[DIVIDES_LCM_NUMSEG];
    ALL_TAC] THEN
  MATCH_MP_TAC INTEGER_SUM THEN X_GEN_TAC `k:num` THEN
  REWRITE_TAC[IN_NUMSEG] THEN STRIP_TAC THEN
  MATCH_MP_TAC INTEGER_SUM THEN X_GEN_TAC `m:num` THEN
  REWRITE_TAC[IN_NUMSEG] THEN STRIP_TAC THEN
  REWRITE_TAC[real_div] THEN ONCE_REWRITE_TAC[REAL_INV_MUL] THEN
  REWRITE_TAC[REAL_ARITH
   `&2 * l * (s * inv(&2) * inv y) * c = s * l * c / y`] THEN
  MATCH_MP_TAC INTEGER_MUL THEN SIMP_TAC[INTEGER_CLOSED] THEN
  MATCH_MP_TAC(MESON[] `!y. integer y /\ x = y ==> integer x`) THEN
  EXISTS_TAC
   `&(LCM (1..n)) pow 3 *
    (&(binom(n,k)) * &(binom(n+k,k)) * &(binom(n-m,n-k)) * &(binom(n+k,k-m))) /
    (&m pow 3 * &(binom(k,m)) pow 2)` THEN
  CONJ_TAC THENL
   [ONCE_REWRITE_TAC[REAL_ARITH `a * b / c:real = b * a / c`] THEN
    MATCH_MP_TAC INTEGER_MUL THEN SIMP_TAC[INTEGER_CLOSED] THEN
    REWRITE_TAC[real_div; REAL_INV_MUL; REAL_INV_POW] THEN
    REWRITE_TAC[REAL_ARITH
      `x pow 3 * y pow 3 * (z:real) pow 2 =
       (x * y) * (x * y * z) * (x * y * z)`] THEN
    REWRITE_TAC[GSYM REAL_INV_MUL] THEN REWRITE_TAC[GSYM real_div] THEN
    MATCH_MP_TAC INTEGER_MUL THEN REWRITE_TAC[INTEGER_DIV] THEN
    CONJ_TAC THENL
     [DISJ2_TAC THEN MATCH_MP_TAC(NUMBER_RULE
       `m * binom(k,m) divides LCM(1..n) ==> m divides LCM(1..n)`);
      MATCH_MP_TAC INTEGER_MUL THEN
      REWRITE_TAC[INTEGER_DIV; REAL_OF_NUM_MUL] THEN DISJ2_TAC] THEN
    TRANS_TAC DIVIDES_TRANS `LCM(1..k)` THEN
    ASM_SIMP_TAC[BINOM_MULTIPLE_DIVIDES_LCM] THEN
    ONCE_REWRITE_TAC[PRIMEPOW_DIVISORS_DIVIDES] THEN
    ASM_SIMP_TAC[IMP_CONJ; PRIMEPOW_DIVIDES_NUMSEG_LCM; LE_1] THEN
    ASM_MESON_TAC[LE_TRANS];
    ALL_TAC] THEN
  AP_TERM_TAC THEN REWRITE_TAC[cc] THEN REWRITE_TAC[real_div] THEN
  ONCE_REWRITE_TAC[REAL_INV_MUL] THEN
  ONCE_REWRITE_TAC[REAL_ARITH `a * b * c:real = b * a * c`] THEN
  AP_TERM_TAC THEN REWRITE_TAC[GSYM real_div] THEN
  SUBGOAL_THEN `m:num <= n` ASSUME_TAC THENL
   [ASM_ARITH_TAC; ALL_TAC] THEN
  ASM_REWRITE_TAC[REAL_OF_NUM_BINOM; LE_ADD;
                  ONCE_REWRITE_RULE[ADD_SYM] LE_ADD] THEN
  REPEAT(COND_CASES_TAC THENL [ALL_TAC; ASM_ARITH_TAC]) THEN
  REWRITE_TAC[ADD_SUB] THEN
  SUBGOAL_THEN
   `n - m - (n - k):num = k - m /\ (n + k) - (k - m) = n + m`
   (fun th -> REWRITE_TAC[th])
  THENL [ASM_ARITH_TAC; ALL_TAC] THEN
  REWRITE_TAC[real_div; REAL_INV_MUL; REAL_POW_2; REAL_INV_INV] THEN
  REWRITE_TAC[ADD_SYM] THEN
  MAP_EVERY (MP_TAC o C SPEC FACT_NZ)
   [`k:num`; `m:num`; `n:num`; `k + n:num`; `m + n:num`;
    `k - m:num`; `n - k:num`; `n - m:num`] THEN
  REWRITE_TAC[GSYM REAL_OF_NUM_EQ] THEN CONV_TAC REAL_FIELD);;

(* ========================================================================= *)
(* *** Part 3: a_n and b_n both satisfy the same recurrence of order 2.      *)
(* ========================================================================= *)

let pp = new_definition
 `pp n k = -- &4 * &k pow 4 *
          (&12 * &n + &4 * &n pow 2 + &8 + &3 * &k - &2 * &k pow 2) *
          (&2 * &n + &3) * cc n k`;;

let qq = new_definition
 `qq n k = (&n + &1 - &k) pow 2 * (&n + &2 - &k) pow 2`;;

(* ------------------------------------------------------------------------- *)
(* Pointwise telescoping identity for the aa recurrence.                     *)
(* ------------------------------------------------------------------------- *)

let CC_STEP_K = prove
 (`!n k. cc n (k + 1) =
         (&n pow 2 - &k pow 2 + &n - &k) pow 2 / (&k + &1) pow 4 *
         cc n k`,
  REPEAT GEN_TAC THEN REWRITE_TAC[cc; ADD_ASSOC; BINOM_BOTH_STEP_REAL] THEN
  REWRITE_TAC[BINOM_BOTTOM_STEP_REAL] THEN
  ONCE_REWRITE_TAC[REAL_ARITH
   `(a * b) pow 2 * (c * d:real) pow 2 =
    (a * c) pow 2 * b pow 2 * d pow 2`] THEN
  REWRITE_TAC[REAL_ARITH
   `(a / c) * (b / c):real = (a * b) * inv(c) * inv(c)`] THEN
  REWRITE_TAC[GSYM REAL_OF_NUM_ADD; GSYM REAL_POW_2] THEN
  REWRITE_TAC[REAL_POW_MUL; REAL_POW_POW] THEN
  CONV_TAC NUM_REDUCE_CONV THEN REWRITE_TAC[GSYM REAL_ADD_ASSOC] THEN
  REWRITE_TAC[REAL_POW_INV; REAL_MUL_ASSOC; real_div] THEN
  REAL_ARITH_TAC);;

let CC_STEP_N = prove
 (`!n k. cc (n + 1) k =
            if k = n + 1 then &4 * &(binom(2 * n + 1,n + 1)) pow 2
            else (&n + &1 + &k) pow 2/ (&n + &1 - &k) pow 2 * cc n k`,
  REWRITE_TAC[ARITH_RULE `2 * n + 1 = 1 + 2 * n`] THEN
  REWRITE_TAC[cc; BINOM_TOP_STEP_REAL;
              ARITH_RULE `(n + 1) + k = (n + k) + 1`] THEN
  REPEAT GEN_TAC THEN REWRITE_TAC[ARITH_RULE `~(k = (n + k) + 1)`] THEN
  COND_CASES_TAC THEN ASM_REWRITE_TAC[GSYM REAL_OF_NUM_ADD] THENL
   [REWRITE_TAC[REAL_POW_ONE; REAL_MUL_RID; REAL_FIELD
     `((&n + &n + &1) + &1) / ((&n + &n + &1) + &1 - (&n + &1)) = &2`] THEN
    REWRITE_TAC[ARITH_RULE `n + n + 1 = 1 + 2 * n`] THEN REAL_ARITH_TAC;
    REWRITE_TAC[REAL_ARITH
     `(x * b:real) pow 2 * (y * c) pow 2 =
      (x * y) pow 2 * b pow 2 * c pow 2`] THEN
    REWRITE_TAC[REAL_MUL_ASSOC] THEN
    REPLICATE_TAC 2 (AP_THM_TAC THEN AP_TERM_TAC) THEN
    POP_ASSUM MP_TAC THEN
    REWRITE_TAC[GSYM REAL_OF_NUM_EQ; GSYM REAL_OF_NUM_ADD] THEN
    CONV_TAC REAL_FIELD]);;

let AA_LEMMA = prove
 (`!n k.
   k <= n
   ==> ((-- &3 * &n pow 2 - &3 * &n - &n pow 3 - &1) * cc n k +
        (&34 * &n pow 3 + &153 * &n pow 2 + &231 * &n + &117) * cc (n + 1) k +
        (-- &n pow 3 - &6 * &n pow 2 - &12 * &n - &8) * cc (n + 2) k) *
       qq n k * qq n (k + 1) =
       pp n k * qq n (k + 1) - pp n (k + 1) * qq n k`,
  REPEAT STRIP_TAC THEN
  REWRITE_TAC[CC_STEP_N; ARITH_RULE `n + 2 = (n + 1) + 1`] THEN
  REPEAT(COND_CASES_TAC THENL [ASM_ARITH_TAC; ASM_REWRITE_TAC[]]) THEN
  REWRITE_TAC[pp; qq; CC_STEP_K] THEN
  REPEAT(FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE RAND_CONV [GSYM
   REAL_OF_NUM_EQ])) THEN
  REWRITE_TAC[GSYM REAL_OF_NUM_ADD] THEN CONV_TAC REAL_FIELD);;

let TELESCOPING_RATIONAL_SUM = prove
 (`!a p q n.
    (!k. k <= n
         ==> a k * q k * q (k + 1) = p k * q(k + 1) - p(k + 1) * q k) /\
    (!k. k <= n ==> ~(p k = &0 /\ q k = &0))
    ==> sum(0..n) (\k. a k) * q 0 * q (n + 1) =
        p 0 * q (n + 1) - p(n + 1) * q 0`,
  REWRITE_TAC[AND_FORALL_THM; TAUT
   `(p ==> r) /\ (q ==> r) <=> p \/ q ==> r`] THEN
  REPLICATE_TAC 3 GEN_TAC THEN INDUCT_TAC THENL
   [DISCH_THEN(MP_TAC o SPEC `0`) THEN SIMP_TAC[LE_REFL; SUM_CLAUSES_NUMSEG];
    REWRITE_TAC[LE; TAUT `p \/ q ==> r <=> (p ==> r) /\ (q ==> r)`] THEN
    REWRITE_TAC[FORALL_AND_THM; FORALL_UNWIND_THM2; SUM_CLAUSES_NUMSEG] THEN
    REWRITE_TAC[ADD1; ARITH_RULE `(n + 1) + 1 = n + 2`] THEN
    STRIP_TAC THEN FIRST_X_ASSUM(MP_TAC o check (is_imp o concl)) THEN
    ASM_REWRITE_TAC[LE_0] THEN
    REPEAT(FIRST_X_ASSUM(MP_TAC o SPEC `n:num`)) THEN
    REWRITE_TAC[LE_REFL] THEN REPEAT(POP_ASSUM MP_TAC) THEN
    CONV_TAC REAL_RING]);;

(* ------------------------------------------------------------------------- *)
(* Truncated form omitting the last summand.                                 *)
(* ------------------------------------------------------------------------- *)

let AA_LEMMA' = prove
 (`!n k.
   k < n
   ==> ((-- &3 * &n pow 2 - &3 * &n - &n pow 3 - &1) * cc n k +
        (&34 * &n pow 3 + &153 * &n pow 2 + &231 * &n + &117) * cc (n + 1) k +
        (-- &n pow 3 - &6 * &n pow 2 - &12 * &n - &8) * cc (n + 2) k) *
       qq n k * qq n (k + 1) =
       pp n k * qq n (k + 1) - pp n (k + 1) * qq n k`,
  MESON_TAC[AA_LEMMA; LT_IMP_LE]);;

let TELESCOPING_RATIONAL_SUM' = prove
 (`!a p q n.
    (!k. k < n
         ==> a k * q k * q (k + 1) = p k * q(k + 1) - p(k + 1) * q k) /\
    (!k. k < n ==> ~(p k = &0 /\ q k = &0))
    ==> (sum(0..n) (\k. a k) - a n) * q 0 * q n =
        p 0 * q n - p n * q 0`,
  REPEAT GEN_TAC THEN ASM_CASES_TAC `n = 0` THENL
   [ASM_REWRITE_TAC[SUM_CLAUSES_NUMSEG] THEN REAL_ARITH_TAC;
    ASM_SIMP_TAC[ARITH_RULE `~(n = 0) ==> (k < n <=> k <= n - 1)`] THEN
    ASM_SIMP_TAC[SUM_CLAUSES_RIGHT; LE_1; LE_0] THEN
    DISCH_THEN(MP_TAC o MATCH_MP TELESCOPING_RATIONAL_SUM) THEN
    ASM_SIMP_TAC[ARITH_RULE `~(n = 0) ==> n - 1 + 1 = n`] THEN
    REAL_ARITH_TAC]);;

(* ------------------------------------------------------------------------- *)
(* The recurrence for aa.                                                    *)
(* ------------------------------------------------------------------------- *)

let AA_RECURRENCE =
  let raw = prove
   (`!n. (-- &3 * &n pow 2 - &3 * &n - &n pow 3 - &1) * aa n +
       (&34 * &n pow 3 + &153 * &n pow 2 + &231 * &n + &117) * aa (n + 1) +
       (-- &n pow 3 - &6 * &n pow 2 - &12 * &n - &8) * aa (n + 2) = &0`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[aa] THEN
  REWRITE_TAC[GSYM ADD1; ARITH_RULE `n + 2 = SUC(SUC n)`] THEN
  REWRITE_TAC[SUM_CLAUSES_NUMSEG; LE_0; GSYM REAL_ADD_ASSOC] THEN
  REWRITE_TAC[REAL_ARITH
   `a * s1 + b * (s2 + x) + c * (s3 + y + z):real =
    (a * s1 + b * s2 + c * s3) + (b * x + c * y + c * z)`] THEN
  REWRITE_TAC[GSYM SUM_LMUL; GSYM SUM_ADD_NUMSEG] THEN
  REWRITE_TAC[ADD1; ARITH_RULE `(n + 1) + 1 = n + 2`] THEN
  MP_TAC(MATCH_MP (ONCE_REWRITE_RULE[IMP_CONJ] TELESCOPING_RATIONAL_SUM')
                  (SPEC `n:num` AA_LEMMA')) THEN
  ANTS_TAC THENL
   [REWRITE_TAC[pp; qq; REAL_ENTIRE; REAL_POW_EQ_0; ARITH; REAL_OF_NUM_EQ] THEN
    REWRITE_TAC[GSYM REAL_OF_NUM_EQ; GSYM REAL_OF_NUM_LT] THEN REAL_ARITH_TAC;
    ALL_TAC] THEN
  REWRITE_TAC[pp; qq] THEN CONV_TAC REAL_RAT_REDUCE_CONV THEN
  REWRITE_TAC[REAL_MUL_LZERO; REAL_MUL_RZERO;
              REAL_ARITH `x + y - x:real = y`] THEN
  CONV_TAC REAL_RAT_REDUCE_CONV THEN
  REWRITE_TAC[REAL_RING
   `x * ((&n + &1) pow 2 * (&n + &2) pow 2) * &4 =
    &0 - y * (&n + &1) pow 2 * (&n + &2) pow 2 <=>
   (x + y / &4) * (&n + &1) pow 2 * (&n + &2) pow 2 = &0`] THEN
  REWRITE_TAC[REAL_ENTIRE; REAL_POW_EQ_0;
              REAL_ARITH `~(&n + &1 = &0) /\ ~(&n + &2 = &0)`] THEN
  REWRITE_TAC[REAL_ARITH
   `(s - a) + (-- &4 * x) / &4 = &0 <=> s = a + x`] THEN
  DISCH_THEN SUBST1_TAC THEN REWRITE_TAC[REAL_ARITH
   `(a * cn + b * cn1 + c * cn2) + x * y * z * cn:real =
    (a + x * y * z) * cn + b * cn1 + c * cn2`] THEN
  REWRITE_TAC[cc; BINOM_REFL] THEN
  REWRITE_TAC[num_CONV `2`; num_CONV `1`; ADD_CLAUSES] THEN
  REWRITE_TAC[ARITH_RULE `n + n = 2 * n`] THEN
  CONV_TAC NUM_REDUCE_CONV THEN
  REWRITE_TAC[ADD1; BINOM_TOP_STEP_REAL; BINOM_BOTTOM_STEP_REAL] THEN
  ASM_CASES_TAC `n = 0` THENL
   [ASM_REWRITE_TAC[] THEN CONV_TAC NUM_REDUCE_CONV THEN
    REWRITE_TAC[BINOM_REFL] THEN
    CONV_TAC REAL_RAT_REDUCE_CONV;
    ALL_TAC] THEN
  ASM_CASES_TAC `n = 1` THENL
   [ASM_REWRITE_TAC[] THEN CONV_TAC NUM_REDUCE_CONV THEN
    REWRITE_TAC[num_CONV `2`; num_CONV `1`; BINOM] THEN
    CONV_TAC NUM_REDUCE_CONV THEN
    CONV_TAC REAL_RAT_REDUCE_CONV;
    ALL_TAC] THEN
  REPEAT(COND_CASES_TAC THENL
   [TRY(FIRST_X_ASSUM(MATCH_MP_TAC o MATCH_MP (TAUT `p ==> ~p ==> q`)) THEN
        ASM_ARITH_TAC);
    ASM_REWRITE_TAC[] THEN POP_ASSUM(K ALL_TAC)]) THEN
  REWRITE_TAC[GSYM REAL_OF_NUM_ADD; GSYM REAL_OF_NUM_MUL] THEN
  UNDISCH_TAC `~(n = 0)` THEN UNDISCH_TAC `~(n = 1)` THEN
  REWRITE_TAC[GSYM REAL_OF_NUM_EQ] THEN
  REWRITE_TAC[BINOM_REFL] THEN
  W(fun (asl,w) ->
    REWRITE_TAC(map (REAL_POLY_CONV o rand)
                    (find_terms (is_binop `(/):real->real->real`) w))) THEN
  CONV_TAC REAL_FIELD) in
  prove
   (`!n. (&n + &2) pow 3 * aa(n + 2) -
         (&2 * &n + &3) * (&17 * &n pow 2 + &51 * &n + &39) * aa(n + 1) +
         (&n + &1) pow 3 * aa(n) = &0`,
    MP_TAC raw THEN MATCH_MP_TAC MONO_FORALL THEN CONV_TAC REAL_RING);;

(* ------------------------------------------------------------------------- *)
(* Split bb n = aa n * zz n + ww n. Here ss is the inner harmonic sum in    *)
(* BB_ALT and ww = sum_{k=0}^n cc(n,k) * ss(n,k). The order-4 operator      *)
(* below is shown to annihilate both aa * zz and ww; its factorisation then  *)
(* yields the order-2 recurrence for bb.                                    *)
(* ------------------------------------------------------------------------- *)

let ss = new_definition
 `ss n k = sum(1..k) (\m. --(&1) pow (m - 1) /
                          (&2 * &m pow 3 * &(binom(n+m,m)) * &(binom(n,m))))`;;

let ww = new_definition
 `ww n = sum(0..n) (\k. cc n k * ss n k)`;;

(* ------------------------------------------------------------------------- *)
(* Contiguity for the harmonic summand and partial sum ss. The single term   *)
(* d_term n m has a clean n-shift, yielding the mixed (n,k)-contiguity       *)
(* SS_SNSK.                                                                 *)
(* ------------------------------------------------------------------------- *)

let d_term = new_definition
 `d_term n m = --(&1) pow (m - 1) /
               (&2 * &m pow 3 * &(binom(n+m,m)) * &(binom(n,m)))`;;

let D_STEP_N = prove
 (`!n m. 1 <= m /\ m <= n
         ==> d_term (n+1) m = (&n + &1 - &m) / (&n + &1 + &m) * d_term n m`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `&m <= &n /\ &1 <= &m` STRIP_ASSUME_TAC THENL
   [ASM_REWRITE_TAC[REAL_OF_NUM_LE]; ALL_TAC] THEN
  REWRITE_TAC[d_term] THEN
  SUBGOAL_THEN `(n + 1) + m = (n + m) + 1` SUBST1_TAC THENL [ARITH_TAC; ALL_TAC] THEN
  MP_TAC(ISPECL [`n+m:num`; `m:num`] BINOM_TOP_STEP_REAL) THEN
  MP_TAC(ISPECL [`n:num`; `m:num`] BINOM_TOP_STEP_REAL) THEN
  REWRITE_TAC[ARITH_RULE `~(m = (n + m) + 1)`] THEN
  ASM_SIMP_TAC[ARITH_RULE `m <= n ==> ~(m = n + 1)`] THEN
  REWRITE_TAC[GSYM REAL_OF_NUM_ADD] THEN
  SUBGOAL_THEN `~(&n + &1 - &m = &0) /\ ~(&n + &1 + &m = &0) /\
                ~((&n + &m) + &1 - &m = &0) /\
                ~(&(binom(n+m,m)) = &0) /\ ~(&(binom(n,m)) = &0) /\ ~(&m = &0)`
  STRIP_ASSUME_TAC THENL
   [REPEAT CONJ_TAC THEN
    TRY(REWRITE_TAC[REAL_OF_NUM_EQ; BINOM_EQ_0; NOT_LT] THEN ASM_ARITH_TAC) THEN
    ASM_REAL_ARITH_TAC;
    ALL_TAC] THEN
  REPEAT(DISCH_THEN(fun th -> REWRITE_TAC[th])) THEN CONV_TAC REAL_FIELD);;

let SS_AS_DTERM = prove
 (`!n k. ss n k = sum(1..k) (\m. d_term n m)`,
  REWRITE_TAC[ss; d_term]);;

let SS_DIFF_K = prove
 (`!n k. ss n (k+1) = ss n k + d_term n (k+1)`,
  REPEAT GEN_TAC THEN REWRITE_TAC[SS_AS_DTERM] THEN
  SUBGOAL_THEN `k + 1 = SUC k` SUBST1_TAC THENL [ARITH_TAC; ALL_TAC] THEN
  SIMP_TAC[SUM_CLAUSES_NUMSEG; ARITH_RULE `1 <= SUC k`] THEN REWRITE_TAC[ADD1]);;

let SS_SNSK = prove
 (`!n k. k < n
         ==> ss (n+1) (k+1) =
             (-- &n + &k) / (&n + &2 + &k) * ss n k + ss (n+1) k +
             (&n - &k) / (&n + &2 + &k) * ss n (k+1)`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[SS_DIFF_K] THEN
  MP_TAC(SPECL [`n:num`; `k+1`] D_STEP_N) THEN
  ANTS_TAC THENL [ASM_ARITH_TAC; DISCH_THEN SUBST1_TAC] THEN
  REWRITE_TAC[GSYM REAL_OF_NUM_ADD] THEN
  SUBGOAL_THEN `~(&n + &2 + &k = &0)` MP_TAC THENL
   [REAL_ARITH_TAC; CONV_TAC REAL_FIELD]);;

let BB_AS_AAZZ_WW = prove
 (`!n. bb n = aa n * zz n + ww n`,
  GEN_TAC THEN REWRITE_TAC[BB_ALT; ww; aa] THEN
  REWRITE_TAC[GSYM SUM_RMUL; GSYM SUM_ADD_NUMSEG] THEN
  MATCH_MP_TAC SUM_EQ_NUMSEG THEN X_GEN_TAC `k:num` THEN STRIP_TAC THEN
  REWRITE_TAC[cc; ss; REAL_ADD_LDISTRIB] THEN
  BINOP_TAC THENL [REAL_ARITH_TAC; ALL_TAC] THEN
  REWRITE_TAC[GSYM SUM_LMUL] THEN
  MATCH_MP_TAC SUM_EQ_NUMSEG THEN X_GEN_TAC `m:num` THEN STRIP_TAC THEN
  REWRITE_TAC[] THEN REAL_ARITH_TAC);;

let ZZ_STEP = prove
 (`!n. zz(n + 1) = zz n + &1 / &(n + 1) pow 3`,
  GEN_TAC THEN REWRITE_TAC[zz] THEN
  SUBGOAL_THEN `n + 1 = SUC n` SUBST1_TAC THENL [ARITH_TAC; ALL_TAC] THEN
  SIMP_TAC[SUM_CLAUSES_NUMSEG; ARITH_RULE `1 <= SUC n`] THEN REWRITE_TAC[ADD1]);;

(* ------------------------------------------------------------------------- *)
(* The b-recurrence via the Apery operator factorisation P_flat = M o L.     *)
(*                                                                           *)
(* L is the order-2 Apery operator, whose vanishing on bb is the goal. The   *)
(* order-4 operator P_flat, recorded in include/ann_v.v and used in          *)
(* theories/ops_for_b.v of the Coq development cited above, factors as the   *)
(* composite M o L for an explicit order-2 M with polynomial coefficients    *)
(* m0c,m1c,m2c. Since P_flat[bb] = 0, this gives M[L bb] = 0. As L bb       *)
(* vanishes at n = 0,1 and m2c is never zero, this forces L bb = 0.          *)
(* ------------------------------------------------------------------------- *)

(* Harrison's original prelude relies on type inference, so enable this only *)
(* for the new development below.                                            *)
type_invention_error := true;;

let lop = new_definition
 `lop (f:num->real) n = (&n + &2) pow 3 * f(n+2) -
       (&2 * &n + &3) * (&17 * &n pow 2 + &51 * &n + &39) * f(n+1) +
       (&n + &1) pow 3 * f(n)`;;

(* Salvy's order-4 creative-telescoping operator for the bb summand. *)
let pflat = new_definition
 `pflat (f:num->real) n =
    (&2 * &n + &7) *
    (&928 + &1266 * &n + &643 * &n pow 2 + &144 * &n pow 3 + &12 * &n pow 4) *
    (&n + &1) pow 6 * f n +
    (--(&1) * (&2 * &n + &3) * (&2 * &n + &7) *
     (&408 * &n pow 9 + &7956 * &n pow 8 + &68086 * &n pow 7 + &336284 * &n pow 6 +
      &1058890 * &n pow 5 + &2209767 * &n pow 4 + &3063206 * &n pow 3 +
      &2724789 * &n pow 2 + &1413006 * &n + &325664)) * f(n+1) +
    (&2 * &n + &5) *
    (&13896 * &n pow 10 + &347400 * &n pow 9 + &3868998 * &n pow 8 +
     &25269960 * &n pow 7 + &107159724 * &n pow 6 + &308199360 * &n pow 5 +
     &608681313 * &n pow 4 + &814935630 * &n pow 3 + &707785777 * &n pow 2 +
     &360083510 * &n + &81495208) * f(n+2) +
    (--(&1) * (&2 * &n + &3) * (&2 * &n + &7) *
     (&408 * &n pow 9 + &10404 * &n pow 8 + &117046 * &n pow 7 + &761526 * &n pow 6 +
      &3153520 * &n pow 5 + &8607233 * &n pow 4 + &15461616 * &n pow 3 +
      &17602001 * &n pow 2 + &11509566 * &n + &3291016)) * f(n+3) +
    (&2 * &n + &3) *
    (&12 * &n pow 4 + &96 * &n pow 3 + &283 * &n pow 2 + &364 * &n + &173) *
    (&n + &4) pow 6 * f(n+4)`;;

(* The order-2 "reducer" M coefficients. *)
let m0c = new_definition
 `m0c n = (&n + &1) pow 3 * (&2 * &n + &7) *
          (&12 * &n pow 4 + &144 * &n pow 3 + &643 * &n pow 2 + &1266 * &n + &928)`;;
let m1c = new_definition
 `m1c n = --(&1) * (&2 * &n + &3) * (&2 * &n + &7) *
          (&204 * &n pow 6 + &3060 * &n pow 5 + &18743 * &n pow 4 + &59930 * &n pow 3 +
           &105413 * &n pow 2 + &96690 * &n + &36184)`;;
let m2c = new_definition
 `m2c n = (&n + &4) pow 3 * (&2 * &n + &3) *
          (&12 * &n pow 4 + &96 * &n pow 3 + &283 * &n pow 2 + &364 * &n + &173)`;;

(* P_flat = M o L : a pure polynomial operator identity. *)
let MOL_FACTOR = prove
 (`!f n. pflat f n = m0c n * lop f n + m1c n * lop f (n+1) + m2c n * lop f (n+2)`,
  REPEAT GEN_TAC THEN REWRITE_TAC[pflat; lop; m0c; m1c; m2c] THEN
  REWRITE_TAC[ARITH_RULE `(n+1)+2 = n+3`; ARITH_RULE `(n+1)+1 = n+2`;
              ARITH_RULE `(n+2)+2 = n+4`; ARITH_RULE `(n+2)+1 = n+3`;
              GSYM REAL_OF_NUM_ADD] THEN
  CONV_TAC REAL_RING);;

let M2C_NONZERO = prove
 (`!n. ~(m2c n = &0)`,
  GEN_TAC THEN REWRITE_TAC[m2c; REAL_ENTIRE; DE_MORGAN_THM] THEN
  REPEAT CONJ_TAC THEN MATCH_MP_TAC(REAL_ARITH `&0 < x ==> ~(x = &0)`) THENL
   [MATCH_MP_TAC REAL_POW_LT THEN REAL_ARITH_TAC;
    REAL_ARITH_TAC;
    MATCH_MP_TAC(REAL_ARITH
     `&0 <= &12 * x pow 4 /\ &0 <= &96 * x pow 3 /\ &0 <= &283 * x pow 2 /\ &0 <= &364 * x
      ==> &0 < &12 * x pow 4 + &96 * x pow 3 + &283 * x pow 2 + &364 * x + &173`) THEN
    REPEAT CONJ_TAC THEN MATCH_MP_TAC REAL_LE_MUL THEN
    REWRITE_TAC[REAL_POS] THEN SIMP_TAC[REAL_POW_LE; REAL_POS]]);;

(* A sequence killed by M and zero at 0 and 1 vanishes, since m2c is never *)
(* zero. *)
let M_KERNEL_TRIVIAL = prove
 (`!g:num->real. (!n. m0c n * g n + m1c n * g(n+1) + m2c n * g(n+2) = &0) /\
       g 0 = &0 /\ g 1 = &0
       ==> !n. g n = &0`,
  GEN_TAC THEN DISCH_THEN(CONJUNCTS_THEN2 ASSUME_TAC STRIP_ASSUME_TAC) THEN
  MATCH_MP_TAC num_WF THEN X_GEN_TAC `n:num` THEN DISCH_TAC THEN
  ASM_CASES_TAC `n = 0` THEN ASM_REWRITE_TAC[] THEN
  ASM_CASES_TAC `n = 1` THEN ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN `g (n - 2):real = &0 /\ g (n - 1):real = &0` STRIP_ASSUME_TAC THENL
   [CONJ_TAC THEN FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_ARITH_TAC; ALL_TAC] THEN
  FIRST_X_ASSUM(fun th ->
    if can (fun () -> find_term (fun t ->
       (try fst(dest_const(fst(strip_comb t)))="m0c" with _ -> false)) (concl th)) ()
    then MP_TAC(SPEC `n - 2` th) else fail()) THEN
  SUBGOAL_THEN `n - 2 + 1 = n - 1 /\ n - 2 + 2 = n` (fun th -> REWRITE_TAC[th]) THENL
   [ASM_ARITH_TAC; ALL_TAC] THEN
  ASM_REWRITE_TAC[REAL_MUL_RZERO; REAL_ADD_LID; REAL_ADD_RID] THEN
  REWRITE_TAC[REAL_ENTIRE; M2C_NONZERO]);;

(* Base cases: L bb vanishes at 0 and 1 (finite evaluation of bb 0..3). *)
let LOP_BB_0 = prove
 (`lop bb 0 = &0`,
  REWRITE_TAC[lop] THEN CONV_TAC NUM_REDUCE_CONV THEN
  REWRITE_TAC[bb; aa; cc; zz; GSYM ADD1] THEN
  REWRITE_TAC[num_CONV `2`; num_CONV `1`; SUM_CLAUSES_NUMSEG] THEN
  CONV_TAC NUM_REDUCE_CONV THEN
  REWRITE_TAC[num_CONV `2`; num_CONV `1`; BINOM] THEN
  CONV_TAC NUM_REDUCE_CONV THEN CONV_TAC REAL_RAT_REDUCE_CONV);;

let LOP_BB_1 = prove
 (`lop bb 1 = &0`,
  REWRITE_TAC[lop] THEN CONV_TAC NUM_REDUCE_CONV THEN
  REWRITE_TAC[bb; aa; cc; zz; GSYM ADD1] THEN
  REWRITE_TAC[num_CONV `3`; num_CONV `2`; num_CONV `1`; SUM_CLAUSES_NUMSEG] THEN
  CONV_TAC NUM_REDUCE_CONV THEN
  REWRITE_TAC[num_CONV `3`; num_CONV `2`; num_CONV `1`; BINOM] THEN
  CONV_TAC NUM_REDUCE_CONV THEN CONV_TAC REAL_RAT_REDUCE_CONV);;

(* ------------------------------------------------------------------------- *)
(* PFLAT decomposes over bb = aa*zz + ww. The aa*zz part is killed          *)
(* algebraically using P_flat = M o L and AA_RECURRENCE. The harmonic kernel *)
(* P_flat[ww] is handled by creative telescoping below.                      *)
(* ------------------------------------------------------------------------- *)

let LOP_AAZZ = prove
 (`!n. lop (\m. aa m * zz m) n =
       (&n + &2) pow 3 * aa(n+2) / (&n + &1) pow 3 + aa(n+2) -
       (&2 * &n + &3) * (&17 * &n pow 2 + &51 * &n + &39) * aa(n+1) / (&n + &1) pow 3`,
  GEN_TAC THEN REWRITE_TAC[lop] THEN BETA_TAC THEN
  MP_TAC(SPEC `n:num` AA_RECURRENCE) THEN
  REWRITE_TAC[ARITH_RULE `n + 2 = (n + 1) + 1`; ZZ_STEP;
              GSYM REAL_OF_NUM_ADD] THEN
  SUBGOAL_THEN `~(&n + &1 = &0) /\ ~(&n + &2 = &0)` MP_TAC THENL
   [REWRITE_TAC[GSYM REAL_OF_NUM_ADD] THEN REAL_ARITH_TAC; ALL_TAC] THEN
  CONV_TAC REAL_FIELD);;

(* The aa 3-term recurrence in the explicit (m+2)^3-leading form, at row m. *)
let AA_REC_ROW = prove
 (`!m. (&m + &2) pow 3 * aa(m+2) =
       (&2 * &m + &3) * (&17 * &m pow 2 + &51 * &m + &39) * aa(m+1) -
       (&m + &1) pow 3 * aa(m)`,
  GEN_TAC THEN MP_TAC(SPEC `m:num` AA_RECURRENCE) THEN
  REWRITE_TAC[ARITH_RULE `(m+1)+1 = m+2`] THEN REAL_ARITH_TAC);;

(* P_flat[aa*zz] = 0 follows from MOL_FACTOR and LOP_AAZZ at three rows, *)
(* together with the aa recurrence at the same rows. *)
let PFLAT_AAZZ = prove
 (`!n. pflat (\m. aa m * zz m) n = &0`,
  GEN_TAC THEN REWRITE_TAC[MOL_FACTOR] THEN
  REWRITE_TAC[LOP_AAZZ; ARITH_RULE `(n+1)+1 = n+2`; ARITH_RULE `(n+2)+1 = n+3`;
              ARITH_RULE `(n+1)+2 = n+3`; ARITH_RULE `(n+2)+2 = n+4`] THEN
  REWRITE_TAC[m0c; m1c; m2c] THEN
  MP_TAC(SPEC `n:num` AA_REC_ROW) THEN
  MP_TAC(SPEC `n+1` AA_REC_ROW) THEN
  MP_TAC(SPEC `n+2` AA_REC_ROW) THEN
  REWRITE_TAC[ARITH_RULE `(n+1)+1 = n+2`; ARITH_RULE `(n+1)+2 = n+3`;
              ARITH_RULE `(n+2)+1 = n+3`; ARITH_RULE `(n+2)+2 = n+4`;
              GSYM REAL_OF_NUM_ADD] THEN
  SUBGOAL_THEN `~(&n + &1 = &0) /\ ~(&n + &2 = &0) /\ ~(&n + &3 = &0)`
    MP_TAC THENL
   [REWRITE_TAC[GSYM REAL_OF_NUM_ADD] THEN REAL_ARITH_TAC; ALL_TAC] THEN
  REPEAT(DISCH_THEN(fun th -> if is_imp(concl th) then ALL_TAC else
                              ASSUME_TAC th) ORELSE STRIP_TAC) THEN
  POP_ASSUM_LIST(MP_TAC o end_itlist CONJ) THEN
  CONV_TAC REAL_FIELD);;

(* The harmonic kernel uses order-2 recurrences for vv = cc * ss and the     *)
(* degree-20 certificate Q_flat recorded in include/ann_v.v. Its interior    *)
(* identity is checked below by triangular rational reduction; the boundary  *)
(* is handled separately.                                                    *)
prioritize_real();;

(* ---- ss order-2 recurrences (D_STEP_K, SS_SK2, SS_SN2) ---- *)
let D_STEP_K = prove
 (`!n m. 1 <= m /\ m + 1 <= n
         ==> d_term n (m+1) =
             --(&m pow 3) / ((&m + &1) * (&n + &m + &1) * (&n - &m)) * d_term n m`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[d_term] THEN
  SUBGOAL_THEN `(m + 1) - 1 = SUC(m - 1)` SUBST1_TAC THENL [ASM_ARITH_TAC; ALL_TAC] THEN
  REWRITE_TAC[real_pow] THEN
  SUBGOAL_THEN `n + m + 1 = (n + m) + 1` SUBST1_TAC THENL [ARITH_TAC; ALL_TAC] THEN
  MP_TAC(ISPECL [`n + m:num`; `m:num`] BINOM_BOTH_STEP_REAL) THEN
  MP_TAC(ISPECL [`n:num`; `m:num`] BINOM_BOTTOM_STEP_REAL) THEN
  DISCH_THEN SUBST1_TAC THEN DISCH_THEN SUBST1_TAC THEN
  SUBGOAL_THEN `&m < &n /\ &1 <= &m` STRIP_ASSUME_TAC THENL
   [REWRITE_TAC[REAL_OF_NUM_LT; REAL_OF_NUM_LE] THEN ASM_ARITH_TAC; ALL_TAC] THEN
  REWRITE_TAC[GSYM REAL_OF_NUM_ADD] THEN
  REWRITE_TAC[REAL_ARITH `(&n + &m) + &1 = &n + &m + &1`] THEN
  SUBGOAL_THEN
   `~(&(binom(n+m,m)) = &0) /\ ~(&(binom(n,m)) = &0) /\
    ~(&m + &1 = &0) /\ ~(&n - &m = &0) /\ ~(&n + &m + &1 = &0) /\ ~(&m = &0)`
   MP_TAC THENL
   [REPEAT CONJ_TAC THEN
     TRY(REWRITE_TAC[REAL_OF_NUM_EQ; BINOM_EQ_0; NOT_LT] THEN ASM_ARITH_TAC) THEN
     ASM_REAL_ARITH_TAC;
    REWRITE_TAC[GSYM REAL_OF_NUM_ADD] THEN CONV_TAC REAL_FIELD]);;

(* The order-2 k-recurrence recorded as Sk2 in annotated_recs_s.v. *)
let SS_SK2 = prove
 (`!n k. k + 1 < n
         ==> ss n (k+2) =
             (--(&1) * (&k + &1) pow 3) /
               ((&k + &2) * (&n + &2 + &k) * (--(&n) + &k + &1)) * ss n k +
             (&2 * &k pow 3 + &8 * &k pow 2 + &11 * &k + &5 - &k * &n - &k * &n pow 2 -
              &2 * &n pow 2 - &2 * &n) /
               ((&k + &2) * (&n + &2 + &k) * (--(&n) + &k + &1)) * ss n (k+1)`,
  REPEAT STRIP_TAC THEN
  SUBST1_TAC(ARITH_RULE `k + 2 = (k + 1) + 1`) THEN
  REWRITE_TAC[SS_DIFF_K] THEN
  MP_TAC(SPECL [`n:num`; `k+1`] D_STEP_K) THEN
  ANTS_TAC THENL [ASM_ARITH_TAC; ALL_TAC] THEN
  REWRITE_TAC[ARITH_RULE `(k+1)+1 = k+2`] THEN
  SUBGOAL_THEN `&(k + 1) = &k + &1` SUBST1_TAC THENL
   [REWRITE_TAC[GSYM REAL_OF_NUM_ADD]; ALL_TAC] THEN
  DISCH_THEN SUBST1_TAC THEN
  SUBGOAL_THEN
   `~(&k + &2 = &0) /\ ~(&n + &2 + &k = &0) /\ ~(--(&n) + &k + &1 = &0) /\
    ~((&k + &1) + &1 = &0)`
   MP_TAC THENL
   [REWRITE_TAC[GSYM REAL_OF_NUM_ADD] THEN
    SUBGOAL_THEN `&k + &1 < &n` MP_TAC THENL
     [REWRITE_TAC[REAL_OF_NUM_ADD; REAL_OF_NUM_LT] THEN ASM_ARITH_TAC;
      REAL_ARITH_TAC];
    REWRITE_TAC[GSYM REAL_OF_NUM_ADD] THEN CONV_TAC REAL_FIELD]);;

(* ------------------------------------------------------------------------- *)
(* SS_SN2 (order 2 in n) replaces the full d-tower of the Coq proof with a   *)
(* direct m-telescoping certificate. For R from D_STEP_K, solve              *)
(* rho(m) = sigma(m + 1) R(m) - sigma(m). The lower boundary sigma(n,1)      *)
(* vanishes and sigma(n,k + 1) = c01(n,k), so summing gives SS_SN2. Its      *)
(* c00, c10 and c01 coefficients are those of s_Sn2 in annotated_recs_s.v.   *)
(* ------------------------------------------------------------------------- *)

(* The k-independent m-telescoping certificate for SS_SN2. *)
let SIGMA_DEF = new_definition
 `sigma_s n m = ((&4 * &n + &6) / (&n + &2) pow 3 * &m pow 3 - (&4 * &n + &6) / (&n + &2) pow 2 * &m pow 2 + (&4 * &n pow 2 + &10 * &n + &6) / (&n + &2) pow 3 * &m) / (&n + &m + &1)`;;

(* Reduce d(n+1,m), d(n+2,m) and d(n,m+1) to d_term n m using D_STEP_N and   *)
(* D_STEP_K. REAL_FIELD then treats d_term n m as an atom.                   *)
let SSN2_SUMMAND = prove
 (`!n k m. 1 <= m /\ m <= k /\ k < n ==> ((((--(&2) - &9 * &n pow 2 + &3 * &k * &n - &6 * &k pow 2 - &n pow 4 - &5 * &n pow 3 - &6 * &k pow 3 - &k * &n pow 3 + &k * &n pow 2 + &4 * &k pow 2 * &n pow 2 + &2 * &k pow 2 * &n - &4 * &k pow 3 * &n - &k - &7 * &n) / ((&n + &2) pow 3 * (&n + &2 + &k))) + (&2 * &k * (&2 * &n + &3) * (&k + &1) * (--(&n) + &k) / ((&n + &2) pow 3 * (&n + &2 + &k)))) * d_term n m + ((&2 * &n + &3) * (&n pow 2 + &3 * &n + &3) / (&n + &2) pow 3) * d_term (n+1) m - d_term (n+2) m = sigma_s n m * d_term n m - sigma_s n (m+1) * d_term n (m+1))`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[SIGMA_DEF] THEN
  SUBGOAL_THEN `d_term (n+1) m = (&n + &1 - &m) / (&n + &1 + &m) * d_term n m`
    SUBST1_TAC THENL [MATCH_MP_TAC D_STEP_N THEN ASM_ARITH_TAC; ALL_TAC] THEN
  SUBGOAL_THEN `d_term (n+2) m = (&n + &2 - &m) / (&n + &2 + &m) * ((&n + &1 - &m) / (&n + &1 + &m) * d_term n m)`
    SUBST1_TAC THENL
   [SUBST1_TAC(ARITH_RULE `n + 2 = (n + 1) + 1`) THEN
    MP_TAC(SPECL [`n+1`; `m:num`] D_STEP_N) THEN ANTS_TAC THENL [ASM_ARITH_TAC; ALL_TAC] THEN
    DISCH_THEN SUBST1_TAC THEN
    MP_TAC(SPECL [`n:num`; `m:num`] D_STEP_N) THEN ANTS_TAC THENL [ASM_ARITH_TAC; ALL_TAC] THEN
    DISCH_THEN SUBST1_TAC THEN REWRITE_TAC[GSYM REAL_OF_NUM_ADD] THEN REAL_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN `d_term n (m+1) = --(&m pow 3) / ((&m + &1) * (&n + &m + &1) * (&n - &m)) * d_term n m`
    SUBST1_TAC THENL [MATCH_MP_TAC D_STEP_K THEN ASM_ARITH_TAC; ALL_TAC] THEN
  REWRITE_TAC[GSYM REAL_OF_NUM_ADD] THEN
  SUBGOAL_THEN
   `~(&n + &2 = &0) /\ ~(&n + &2 + &k = &0) /\ ~(&n + &1 + &m = &0) /\ ~(&n + &2 + &m = &0) /\ ~(&m + &1 = &0) /\ ~(&n + &m + &1 = &0) /\ ~(&n - &m = &0) /\ ~(&n + (&m + &1) + &1 = &0)`
   MP_TAC THENL
   [SUBGOAL_THEN `&m < &n` ASSUME_TAC THENL
     [REWRITE_TAC[REAL_OF_NUM_LT] THEN ASM_ARITH_TAC; ALL_TAC] THEN
    REPEAT CONJ_TAC THEN ASM_REAL_ARITH_TAC;
    CONV_TAC REAL_FIELD]);;

let SIGMA_1 = prove
 (`!n. sigma_s n 1 = &0`,
  GEN_TAC THEN REWRITE_TAC[SIGMA_DEF] THEN
  SUBGOAL_THEN `~(&n + &2 = &0) /\ ~(&n + &1 + &1 = &0)` MP_TAC THENL
   [REWRITE_TAC[GSYM REAL_OF_NUM_ADD] THEN REAL_ARITH_TAC;
    REWRITE_TAC[REAL_MUL_RID; REAL_POW_ONE] THEN CONV_TAC REAL_FIELD]);;

let SIGMA_KP1 = prove
 (`!n k. sigma_s n (k+1) = &2 * &k * (&2 * &n + &3) * (&k + &1) * (--(&n) + &k) / ((&n + &2) pow 3 * (&n + &2 + &k))`,
  REPEAT GEN_TAC THEN REWRITE_TAC[SIGMA_DEF] THEN
  SUBGOAL_THEN `~(&n + &2 = &0) /\ ~(&n + (&k + &1) + &1 = &0) /\ ~(&n + &2 + &k = &0)` MP_TAC THENL
   [REWRITE_TAC[GSYM REAL_OF_NUM_ADD] THEN
    SUBGOAL_THEN `&0 <= &n /\ &0 <= &k` MP_TAC THENL
     [REWRITE_TAC[REAL_POS]; REAL_ARITH_TAC];
    REWRITE_TAC[GSYM REAL_OF_NUM_ADD] THEN CONV_TAC REAL_FIELD]);;

(* Sum the per-m identity over m=1..k. The right side telescopes, and the    *)
(* boundary terms are SIGMA_1 and SIGMA_KP1.                                 *)
let SSN2_SUMEQ = prove
 (`!n k. 1 <= k /\ k < n ==> sum(1..k) (\m. (((--(&2) - &9 * &n pow 2 + &3 * &k * &n - &6 * &k pow 2 - &n pow 4 - &5 * &n pow 3 - &6 * &k pow 3 - &k * &n pow 3 + &k * &n pow 2 + &4 * &k pow 2 * &n pow 2 + &2 * &k pow 2 * &n - &4 * &k pow 3 * &n - &k - &7 * &n) / ((&n + &2) pow 3 * (&n + &2 + &k))) + (&2 * &k * (&2 * &n + &3) * (&k + &1) * (--(&n) + &k) / ((&n + &2) pow 3 * (&n + &2 + &k)))) * d_term n m + ((&2 * &n + &3) * (&n pow 2 + &3 * &n + &3) / (&n + &2) pow 3) * d_term (n+1) m - d_term (n+2) m) = sum(1..k) (\m. sigma_s n m * d_term n m - sigma_s n (m+1) * d_term n (m+1))`,
  REPEAT STRIP_TAC THEN MATCH_MP_TAC SUM_EQ_NUMSEG THEN REPEAT STRIP_TAC THEN BETA_TAC THEN
  MATCH_MP_TAC SSN2_SUMMAND THEN ASM_ARITH_TAC);;

let SSN2_LHS = prove
 (`!n k. sum(1..k) (\m. (((--(&2) - &9 * &n pow 2 + &3 * &k * &n - &6 * &k pow 2 - &n pow 4 - &5 * &n pow 3 - &6 * &k pow 3 - &k * &n pow 3 + &k * &n pow 2 + &4 * &k pow 2 * &n pow 2 + &2 * &k pow 2 * &n - &4 * &k pow 3 * &n - &k - &7 * &n) / ((&n + &2) pow 3 * (&n + &2 + &k))) + (&2 * &k * (&2 * &n + &3) * (&k + &1) * (--(&n) + &k) / ((&n + &2) pow 3 * (&n + &2 + &k)))) * d_term n m + ((&2 * &n + &3) * (&n pow 2 + &3 * &n + &3) / (&n + &2) pow 3) * d_term (n+1) m - d_term (n+2) m) = (((--(&2) - &9 * &n pow 2 + &3 * &k * &n - &6 * &k pow 2 - &n pow 4 - &5 * &n pow 3 - &6 * &k pow 3 - &k * &n pow 3 + &k * &n pow 2 + &4 * &k pow 2 * &n pow 2 + &2 * &k pow 2 * &n - &4 * &k pow 3 * &n - &k - &7 * &n) / ((&n + &2) pow 3 * (&n + &2 + &k))) + (&2 * &k * (&2 * &n + &3) * (&k + &1) * (--(&n) + &k) / ((&n + &2) pow 3 * (&n + &2 + &k)))) * ss n k + ((&2 * &n + &3) * (&n pow 2 + &3 * &n + &3) / (&n + &2) pow 3) * ss (n+1) k - ss (n+2) k`,
  REPEAT GEN_TAC THEN REWRITE_TAC[SUM_SUB_NUMSEG; SUM_ADD_NUMSEG; SUM_LMUL] THEN
  REWRITE_TAC[GSYM SS_AS_DTERM]);;

let SS_SN2 = prove
 (`!n k. 1 <= k /\ k < n ==> ss (n+2) k = ((--(&2) - &9 * &n pow 2 + &3 * &k * &n - &6 * &k pow 2 - &n pow 4 - &5 * &n pow 3 - &6 * &k pow 3 - &k * &n pow 3 + &k * &n pow 2 + &4 * &k pow 2 * &n pow 2 + &2 * &k pow 2 * &n - &4 * &k pow 3 * &n - &k - &7 * &n) / ((&n + &2) pow 3 * (&n + &2 + &k))) * ss n k + ((&2 * &n + &3) * (&n pow 2 + &3 * &n + &3) / (&n + &2) pow 3) * ss (n+1) k + (&2 * &k * (&2 * &n + &3) * (&k + &1) * (--(&n) + &k) / ((&n + &2) pow 3 * (&n + &2 + &k))) * ss n (k+1)`,
  REPEAT STRIP_TAC THEN
  MP_TAC(SPECL [`n:num`; `k:num`] SSN2_SUMEQ) THEN ASM_REWRITE_TAC[] THEN
  REWRITE_TAC[SSN2_LHS] THEN
  MP_TAC(SPECL [`1`; `k:num`]
    (INST [`\m. sigma_s n m * d_term n m`,`f:num->real`] SUM_DIFFS)) THEN
  ASM_REWRITE_TAC[] THEN BETA_TAC THEN
  DISCH_THEN(fun th -> DISCH_THEN(MP_TAC o CONV_RULE(RAND_CONV(REWRITE_CONV[th])))) THEN
  REWRITE_TAC[SIGMA_1; SIGMA_KP1; REAL_MUL_LZERO; REAL_SUB_LZERO] THEN
  REWRITE_TAC[SS_DIFF_K] THEN REWRITE_TAC[REAL_ADD_LDISTRIB] THEN
  DISCH_THEN(fun th -> MP_TAC th) THEN REAL_ARITH_TAC);;

(* ---- v=cc*ss recurrences (vv, V_SK2, V_SNSK, V_SN2) ---- *)
let vv = new_definition `vv n k = cc n k * ss n k`;;

(* The order-2 k-recurrence recorded as Sk2 in include/ann_v.v. *)
let V_SK2 = prove
 (`!n k. k + 1 < n ==> vv n (k+2) = (--(&1) * (&n + &2 + &k) * (--(&n) + &k + &1) * (&n + &1 + &k) pow 2 * (--(&n) + &k) pow 2 / ((&k + &1) * (&k + &2) pow 5)) * vv n k + ((&n + &2 + &k) * (--(&n) + &k + &1) * (&2 * &k pow 3 + &8 * &k pow 2 + &11 * &k + &5 - &k * &n - &k * &n pow 2 - &2 * &n pow 2 - &2 * &n) / (&k + &2) pow 5) * vv n (k+1)`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[vv] THEN
  MP_TAC(SPECL[`n:num`;`k:num`] SS_SK2) THEN ASM_REWRITE_TAC[] THEN DISCH_THEN SUBST1_TAC THEN
  SUBST1_TAC(ARITH_RULE `k + 2 = (k + 1) + 1`) THEN REWRITE_TAC[CC_STEP_K] THEN
  MP_TAC(SPECL[`n:num`;`k+1`] CC_STEP_K) THEN REWRITE_TAC[] THEN DISCH_THEN SUBST1_TAC THEN
  MP_TAC(SPECL[`n:num`;`k:num`] CC_STEP_K) THEN DISCH_THEN SUBST1_TAC THEN
  REWRITE_TAC[GSYM REAL_OF_NUM_ADD] THEN
  SUBGOAL_THEN `~(&k + &1 = &0) /\ ~(&k + &2 = &0) /\ ~(&n + &2 + &k = &0) /\ ~(--(&n) + &k + &1 = &0)` MP_TAC THENL
   [REWRITE_TAC[GSYM REAL_OF_NUM_ADD] THEN
    SUBGOAL_THEN `&k + &1 < &n` MP_TAC THENL
     [REWRITE_TAC[REAL_OF_NUM_ADD; REAL_OF_NUM_LT] THEN ASM_ARITH_TAC; REAL_ARITH_TAC];
    REWRITE_TAC[GSYM REAL_OF_NUM_ADD; REAL_ARITH `(&k + &1) + &1 = &k + &2`] THEN CONV_TAC REAL_FIELD]);;

(* Clean cc ratio helpers for k < n, avoiding the conditional in CC_STEP_N. *)
let CC_NR = prove
 (`!n k. k < n ==> cc (n+1) k = (&n + &1 + &k) pow 2 / (&n + &1 - &k) pow 2 * cc n k`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[CC_STEP_N] THEN COND_CASES_TAC THENL [ASM_ARITH_TAC; REWRITE_TAC[]]);;

let CC_N2R = prove
 (`!n k. k < n ==> cc (n+2) k = (&n + &2 + &k) pow 2 / (&n + &2 - &k) pow 2 * ((&n + &1 + &k) pow 2 / (&n + &1 - &k) pow 2 * cc n k)`,
  REPEAT STRIP_TAC THEN SUBST1_TAC(ARITH_RULE `n + 2 = (n + 1) + 1`) THEN
  MP_TAC(SPECL[`n+1`;`k:num`] CC_NR) THEN ANTS_TAC THENL [ASM_ARITH_TAC; ALL_TAC] THEN
  DISCH_THEN SUBST1_TAC THEN MP_TAC(SPECL[`n:num`;`k:num`] CC_NR) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN SUBST1_TAC THEN REWRITE_TAC[GSYM REAL_OF_NUM_ADD] THEN
  REWRITE_TAC[REAL_ARITH `(&n + &1) + &1 = &n + &2`; REAL_ARITH `(&n + &1) + &1 + &k = &n + &2 + &k`;
              REAL_ARITH `(&n + &1) + &1 - &k = &n + &2 - &k`]);;

(* V_SNSK is order 2 in (n,k). Reduce the cc ratios to cc n k and use *)
(* SS_SNSK; the remaining atoms are ss n k, ss(n+1) k and ss n (k+1). *)
let V_SNSK = prove
 (`!n k. k < n ==> vv (n+1) (k+1) = ((&n + &2 + &k) * (--(&n) + &k) * (&n + &1 + &k) pow 2 / (&k + &1) pow 4) * vv n k + ((&n + &2 + &k) pow 2 * (--(&n) - &1 + &k) pow 2 / (&k + &1) pow 4) * vv (n+1) k + ((--(&n) - &2 - &k) / (--(&n) + &k)) * vv n (k+1)`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[vv] THEN
  MP_TAC(SPECL[`n:num`;`k:num`] SS_SNSK) THEN ASM_REWRITE_TAC[] THEN DISCH_THEN SUBST1_TAC THEN
  REWRITE_TAC[CC_STEP_K] THEN
  MP_TAC(SPECL[`n:num`;`k:num`] CC_NR) THEN ASM_REWRITE_TAC[] THEN DISCH_THEN SUBST1_TAC THEN
  REWRITE_TAC[CC_STEP_K; GSYM REAL_OF_NUM_ADD] THEN
  SUBGOAL_THEN `~(&k + &1 = &0) /\ ~(&n + &2 + &k = &0) /\ ~(&n + &1 - &k = &0) /\ ~(--(&n) + &k = &0)` MP_TAC THENL
   [REWRITE_TAC[GSYM REAL_OF_NUM_ADD] THEN
    SUBGOAL_THEN `&k < &n` MP_TAC THENL
     [REWRITE_TAC[REAL_OF_NUM_LT] THEN ASM_ARITH_TAC; REAL_ARITH_TAC];
    REWRITE_TAC[GSYM REAL_OF_NUM_ADD] THEN CONV_TAC REAL_FIELD]);;

(* V_SN2 is order 2 in n. Normalize sign-equal squared denominators before   *)
(* REAL_FIELD to reduce the denominator set.                                 *)
let V_SN2 = prove
 (`!n k. 1 <= k /\ k < n ==> vv (n+2) k = (--(&1) * (&n + &2 + &k) * (&2 + &9 * &n pow 2 - &3 * &k * &n + &6 * &k pow 2 + &n pow 4 + &5 * &n pow 3 + &6 * &k pow 3 + &k * &n pow 3 - &k * &n pow 2 - &4 * &k pow 2 * &n pow 2 - &2 * &k pow 2 * &n + &4 * &k pow 3 * &n + &k + &7 * &n) * (&n + &1 + &k) pow 2 / ((&n + &2) pow 3 * (--(&n) - &1 + &k) pow 2 * (&k - &n - &2) pow 2)) * vv n k + ((&2 * &n + &3) * (&n pow 2 + &3 * &n + &3) * (&n + &2 + &k) pow 2 / ((&n + &2) pow 3 * (&k - &n - &2) pow 2)) * vv (n+1) k + (&2 * &k * (&2 * &n + &3) * (&k + &1) pow 5 * (&n + &2 + &k) / ((&n + &2) pow 3 * (--(&n) + &k) * (--(&n) - &1 + &k) pow 2 * (&k - &n - &2) pow 2)) * vv n (k+1)`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[vv] THEN
  MP_TAC(SPECL[`n:num`;`k:num`] SS_SN2) THEN ASM_REWRITE_TAC[] THEN DISCH_THEN SUBST1_TAC THEN
  MP_TAC(SPECL[`n:num`;`k:num`] CC_N2R) THEN ASM_REWRITE_TAC[] THEN DISCH_THEN SUBST1_TAC THEN
  MP_TAC(SPECL[`n:num`;`k:num`] CC_NR) THEN ASM_REWRITE_TAC[] THEN DISCH_THEN SUBST1_TAC THEN
  REWRITE_TAC[CC_STEP_K] THEN
  REWRITE_TAC[REAL_ARITH `(--(&n) - &1 + &k) pow 2 = (&n + &1 - &k) pow 2`;
              REAL_ARITH `(&k - &n - &2) pow 2 = (&n + &2 - &k) pow 2`] THEN
  REWRITE_TAC[GSYM REAL_OF_NUM_ADD] THEN
  SUBGOAL_THEN `~(&k + &1 = &0) /\ ~(&n + &2 = &0) /\ ~(&n + &2 - &k = &0) /\ ~(&n + &1 - &k = &0) /\ ~(&n + &2 + &k = &0) /\ ~(--(&n) + &k = &0)` MP_TAC THENL
   [REWRITE_TAC[GSYM REAL_OF_NUM_ADD] THEN
    SUBGOAL_THEN `&k < &n` MP_TAC THENL
     [REWRITE_TAC[REAL_OF_NUM_LT] THEN ASM_ARITH_TAC; REAL_ARITH_TAC];
    REWRITE_TAC[GSYM REAL_OF_NUM_ADD] THEN CONV_TAC REAL_FIELD]);;

