  STRIP_TAC THEN MP_TAC(SPECL[`n:num`;`k:num`]V_SN2) THEN ASM_REWRITE_TAC[] THEN DISCH_THEN SUBST1_TAC THEN SUBGOAL_THEN `~(&n + &2 = &0) /\ ~(&n + &1 - &k = &0) /\ ~(&n + &2 - &k = &0) /\ ~(-- &n + &k = &0)` MP_TAC THENL [SUBGOAL_THEN `&k < &n` MP_TAC THENL [REWRITE_TAC[REAL_OF_NUM_LT] THEN ASM_ARITH_TAC; ALL_TAC] THEN STRIP_TAC THEN REPEAT CONJ_TAC THEN ASM_REAL_ARITH_TAC; REWRITE_TAC[REAL_RING `(&k - &n - &2) pow 2 = (&n + &2 - &k) pow 2`] THEN CONV_TAC REAL_FIELD]);;

let V_SNSK_CL = prove
 (`(k:num) < n ==> ((&k + &1) pow 4 * (-- &n + &k)) * vv (n + 1) (k + 1) = (&n pow 5 + &n pow 4 * &k - &2 * &n pow 3 * &k pow 2 - &2 * &n pow 2 * &k pow 3 + &n * &k pow 4 + &k pow 5 + &4 * &n pow 4 - &8 * &n pow 2 * &k pow 2 + &4 * &k pow 4 + &5 * &n pow 3 - &5 * &n pow 2 * &k - &5 * &n * &k pow 2 + &5 * &k pow 3 + &2 * &n pow 2 - &4 * &n * &k + &2 * &k pow 2) * vv n k + (-- &n pow 5 + &n pow 4 * &k + &2 * &n pow 3 * &k pow 2 - &2 * &n pow 2 * &k pow 3 - &n * &k pow 4 + &k pow 5 - &6 * &n pow 4 + &8 * &n pow 3 * &k + &4 * &n pow 2 * &k pow 2 - &8 * &n * &k pow 3 + &2 * &k pow 4 - &13 * &n pow 3 + &19 * &n pow 2 * &k - &3 * &n * &k pow 2 - &3 * &k pow 3 - &12 * &n pow 2 + &16 * &n * &k - &4 * &k pow 2 - &4 * &n + &4 * &k) * vv (n + 1) k + (-- &n * &k pow 4 - &k pow 5 - &4 * &n * &k pow 3 - &6 * &k pow 4 - &6 * &n * &k pow 2 - &14 * &k pow 3 - &4 * &n * &k - &16 * &k pow 2 - &n - &9 * &k - &2) * vv n (k + 1)`,
  STRIP_TAC THEN MP_TAC(SPECL[`n:num`;`k:num`]V_SNSK) THEN ASM_REWRITE_TAC[] THEN DISCH_THEN SUBST1_TAC THEN SUBGOAL_THEN `~(&k + &1 = &0) /\ ~(-- &n + &k = &0)` MP_TAC THENL [SUBGOAL_THEN `&k < &n` MP_TAC THENL [REWRITE_TAC[REAL_OF_NUM_LT] THEN ASM_ARITH_TAC; ALL_TAC] THEN STRIP_TAC THEN REPEAT CONJ_TAC THEN ASM_REAL_ARITH_TAC; CONV_TAC REAL_FIELD]);;

let V_SK2_CL = prove
 (`(k:num) + 1 < n ==> ((&k + &1) * (&k + &2) pow 5) * vv n (k + 2) = (&n pow 6 - &3 * &n pow 4 * &k pow 2 + &3 * &n pow 2 * &k pow 4 - &k pow 6 + &3 * &n pow 5 - &5 * &n pow 4 * &k - &6 * &n pow 3 * &k pow 2 + &10 * &n pow 2 * &k pow 3 + &3 * &n * &k pow 4 - &5 * &k pow 5 + &n pow 4 - &10 * &n pow 3 * &k + &8 * &n pow 2 * &k pow 2 + &10 * &n * &k pow 3 - &9 * &k pow 4 - &3 * &n pow 3 - &n pow 2 * &k + &11 * &n * &k pow 2 - &7 * &k pow 3 - &2 * &n pow 2 + &4 * &n * &k - &2 * &k pow 2) * vv n k + (&n pow 4 * &k pow 2 - &3 * &n pow 2 * &k pow 4 + &2 * &k pow 6 + &3 * &n pow 4 * &k + &2 * &n pow 3 * &k pow 2 - &16 * &n pow 2 * &k pow 3 - &3 * &n * &k pow 4 + &16 * &k pow 5 + &2 * &n pow 4 + &6 * &n pow 3 * &k - &31 * &n pow 2 * &k pow 2 - &16 * &n * &k pow 3 + &53 * &k pow 4 + &4 * &n pow 3 - &25 * &n pow 2 * &k - &32 * &n * &k pow 2 + &93 * &k pow 3 - &7 * &n pow 2 - &28 * &n * &k + &91 * &k pow 2 - &9 * &n + &47 * &k + &10) * vv n (k + 1)`,
  STRIP_TAC THEN MP_TAC(SPECL[`n:num`;`k:num`]V_SK2) THEN ASM_REWRITE_TAC[] THEN DISCH_THEN SUBST1_TAC THEN SUBGOAL_THEN `~(&k + &1 = &0) /\ ~(&k + &2 = &0)` MP_TAC THENL [REWRITE_TAC[GSYM REAL_OF_NUM_ADD] THEN STRIP_TAC THEN REPEAT CONJ_TAC THEN REAL_ARITH_TAC; CONV_TAC REAL_FIELD]);;

(* ------------------------------------------------------------------------- *)
(* Reduce the interior telescoping identity triangularly through the *)
(* rational recurrences to three base values of vv. *)
(* ------------------------------------------------------------------------- *)

let CANCEL_LEM = prove
 (`!d a b:real. ~(d = &0) /\ d * a = d * b ==> a = b`,
  MESON_TAC[REAL_EQ_MUL_LCANCEL]);;


(* Rational-clearing certificate infrastructure. *)
let RAT_ADD = prove
 (`!a b c d:real.
        ~(b = &0) /\ ~(d = &0)
        ==> a / b + c / d = (a * d + c * b) / (b * d)`,
  CONV_TAC REAL_FIELD);;

let RAT_SUB = prove
 (`!a b c d:real.
        ~(b = &0) /\ ~(d = &0)
        ==> a / b - c / d = (a * d - c * b) / (b * d)`,
  CONV_TAC REAL_FIELD);;

let RAT_MUL = prove
 (`!a b c d:real.
        ~(b = &0) /\ ~(d = &0)
        ==> (a / b) * (c / d) = (a * c) / (b * d)`,
  CONV_TAC REAL_FIELD);;

let RAT_NEG = prove
 (`!a b:real. --(a / b) = (--a) / b`,
  REWRITE_TAC[real_div; REAL_MUL_LNEG]);;

let RAT_INV = prove
 (`!a b:real. ~(a = &0) /\ ~(b = &0) ==> inv(a / b) = b / a`,
  CONV_TAC REAL_FIELD);;

let RAT_DIV = prove
 (`!a b c d:real.
        ~(b = &0) /\ ~(c = &0) /\ ~(d = &0)
        ==> (a / b) / (c / d) = (a * d) / (b * c)`,
  CONV_TAC REAL_FIELD);;

let RAT_EQ_CROSS = prove
 (`!a b c d:real.
        ~(b = &0) /\ ~(d = &0)
        ==> (a / b = c / d <=> a * d = c * b)`,
  CONV_TAC REAL_FIELD);;
let REAL_POW_NZ = prove(`!x n. ~(x = &0) ==> ~(x pow n = &0)`, SIMP_TAC[REAL_POW_EQ_0]);;
let REAL_MUL_NZ = prove(`!x y. ~(x = &0) /\ ~(y = &0) ==> ~(x * y = &0)`, REWRITE_TAC[REAL_ENTIRE; DE_MORGAN_THM]);;
let div_tm = `(/):real->real->real` and inv_tm = `inv:real->real`
and mul_tm = `( * ):real->real->real` and add_tm = `(+):real->real->real`
and sub_tm = `(-):real->real->real` and pow_tm = `(pow):real->num->real`
and neg_tm = `(--):real->real`;;
let DIV1 = GSYM REAL_DIV_1;;
let dest_div = dest_binop div_tm;;
let is_binop_op op t = is_comb t && is_comb(rator t) && rator(rator t) = op;;
let has_div t = can (find_term (fun s -> is_binop_op div_tm s || (is_comb s && rator s = inv_tm))) t;;
let rec PROVE_NZ nz_thms d =
  if is_binop_op mul_tm d then let a,b = dest_binop mul_tm d in
    MATCH_MP REAL_MUL_NZ (CONJ (PROVE_NZ nz_thms a) (PROVE_NZ nz_thms b))
  else if is_binop_op pow_tm d then let a,n = dest_binop pow_tm d in
    MATCH_MP (SPECL[a;n] REAL_POW_NZ) (PROVE_NZ nz_thms a)
  else try find (fun th -> concl th = mk_neg(mk_eq(d,`&0`))) nz_thms
    with Failure _ -> (try EQT_ELIM(REAL_RAT_REDUCE_CONV (mk_neg(mk_eq(d,`&0`))))
       with _ -> failwith ("PROVE_NZ: "^string_of_term d));;
let rec RATIONALIZE_CONV nz t =
  if not (has_div t) then SPEC t DIV1
  else if is_binop_op add_tm t then
    let a,b = dest_binop add_tm t in
    let tha = RATIONALIZE_CONV nz a and thb = RATIONALIZE_CONV nz b in
    let na,da = dest_div (rhs(concl tha)) and nb,db = dest_div (rhs(concl thb)) in
    TRANS (MK_COMB(AP_TERM add_tm tha, thb)) (MP (SPECL [na;da;nb;db] RAT_ADD) (CONJ (PROVE_NZ nz da)(PROVE_NZ nz db)))
  else if is_binop_op sub_tm t then
    let a,b = dest_binop sub_tm t in
    let tha = RATIONALIZE_CONV nz a and thb = RATIONALIZE_CONV nz b in
    let na,da = dest_div (rhs(concl tha)) and nb,db = dest_div (rhs(concl thb)) in
    TRANS (MK_COMB(AP_TERM sub_tm tha, thb)) (MP (SPECL [na;da;nb;db] RAT_SUB) (CONJ (PROVE_NZ nz da)(PROVE_NZ nz db)))
  else if is_binop_op mul_tm t then
    let a,b = dest_binop mul_tm t in
    let tha = RATIONALIZE_CONV nz a and thb = RATIONALIZE_CONV nz b in
    let na,da = dest_div (rhs(concl tha)) and nb,db = dest_div (rhs(concl thb)) in
    TRANS (MK_COMB(AP_TERM mul_tm tha, thb)) (MP (SPECL [na;da;nb;db] RAT_MUL) (CONJ (PROVE_NZ nz da)(PROVE_NZ nz db)))
  else if is_binop_op div_tm t then
    let a,b = dest_div t in
    let tha = RATIONALIZE_CONV nz a and thb = RATIONALIZE_CONV nz b in
    let na,da = dest_div (rhs(concl tha)) and nb,db = dest_div (rhs(concl thb)) in
    TRANS (MK_COMB(AP_TERM div_tm tha, thb)) (MP (SPECL [na;da;nb;db] RAT_DIV) (CONJ (PROVE_NZ nz da)(CONJ (PROVE_NZ nz nb)(PROVE_NZ nz db))))
  else if is_binop_op pow_tm t then
    let a,nn = dest_binop pow_tm t in
    let tha = RATIONALIZE_CONV nz a in
    let na,da = dest_div (rhs(concl tha)) in
    TRANS (AP_THM (AP_TERM pow_tm tha) nn) (SPECL [na;da;nn] REAL_POW_DIV)
  else if is_comb t && rator t = inv_tm then
    let a = rand t in let tha = RATIONALIZE_CONV nz a in
    let na,da = dest_div (rhs(concl tha)) in
    TRANS (AP_TERM inv_tm tha) (MP (SPECL [na;da] RAT_INV) (CONJ (PROVE_NZ nz na)(PROVE_NZ nz da)))
  else if is_comb t && rator t = neg_tm then
    let a = rand t in let tha = RATIONALIZE_CONV nz a in
    let na,da = dest_div (rhs(concl tha)) in
    TRANS (AP_TERM neg_tm tha) (SPECL[na;da] RAT_NEG)
  else SPEC t DIV1;;
let prove_rat_eq nz tm =
  let l,r = dest_eq tm in
  let thl = RATIONALIZE_CONV nz l and thr = RATIONALIZE_CONV nz r in
  let nl,dl = dest_div(rhs(concl thl)) and nr,dr = dest_div(rhs(concl thr)) in
  let cross = MP (SPECL [nl;dl;nr;dr] RAT_EQ_CROSS) (CONJ (PROVE_NZ nz dl)(PROVE_NZ nz dr)) in
  let polygoal = rhs(concl cross) in
  let pl,pr = dest_eq polygoal in
  let polyth = TRANS (REAL_POLY_CONV pl) (SYM(REAL_POLY_CONV pr)) in
  let step1 = MK_COMB(AP_TERM `(=):real->real->bool` thl, thr) in
  EQ_MP (SYM (TRANS step1 cross)) polyth;;
let prove_factor_nz_imp f =
  prove(mk_imp(`1 <= k /\ k + 1 < n`, mk_neg(mk_eq(f, `&0`))),
    REWRITE_TAC[GSYM REAL_OF_NUM_ADD; GSYM REAL_OF_NUM_LT; GSYM REAL_OF_NUM_LE] THEN
    STRIP_TAC THEN REWRITE_TAC[GSYM REAL_OF_NUM_ADD] THEN ASM_REAL_ARITH_TAC);;
let rec denom_factors t acc =
  if is_binop_op div_tm t then let a,b = dest_div t in denom_factors a (factor_collect b (denom_factors b acc))
  else match t with Comb(f,x) -> denom_factors f (denom_factors x acc) | Abs(_,b) -> denom_factors b acc | _ -> acc
and factor_collect d acc =
  if is_binop_op mul_tm d then let a,b=dest_binop mul_tm d in factor_collect a (factor_collect b acc)
  else if is_binop_op pow_tm d then let a,_=dest_binop pow_tm d in factor_collect a acc
  else if mem d acc then acc else d::acc;;
let hyp_thm = ASSUME `1 <= k /\ k + 1 < n`;;
let nz_for t = map (fun f -> MP (prove_factor_nz_imp f) hyp_thm) (denom_factors t []);;

(* The telescoping identity reduces via rational recurrences to three base *)
(* values of vv. The displayed rational reductions are untrusted generated *)
(* data; HOL checks every reduction and the final polynomial identities. *)

let V_SN2_CL_G = GEN `n:num` (GEN `k:num` V_SN2_CL);;
let V_SNSK_CL_G = GEN `n:num` (GEN `k:num` V_SNSK_CL);;
let V_SK2_CL_G = GEN `n:num` (GEN `k:num` V_SK2_CL);;

let idx_norm =
  [ARITH_RULE `(n+1)+2 = n+3`;
   ARITH_RULE `(n+1)+1 = n+2`;
   ARITH_RULE `(n+2)+2 = n+4`;
   ARITH_RULE `(n+2)+1 = n+3`];;

let apery_hyp = `1 <= k /\ k + 1 < n`;;

let apery_lift_recurrence th =
  let _,eq = dest_imp(concl th) in
  prove
   (mk_imp(apery_hyp,eq),
    DISCH_TAC THEN MATCH_MP_TAC th THEN ASM_ARITH_TAC);;

let apery_recurrences =
  map UNDISCH
   [apery_lift_recurrence
      (REWRITE_RULE idx_norm (SPECL [`n+2`; `k:num`] V_SN2));
    apery_lift_recurrence
      (REWRITE_RULE idx_norm (SPECL [`n+1`; `k:num`] V_SNSK));
    apery_lift_recurrence
      (REWRITE_RULE idx_norm (SPECL [`n+1`; `k:num`] V_SN2));
    apery_lift_recurrence (SPECL [`n:num`; `k:num`] V_SN2);
    apery_lift_recurrence (SPECL [`n:num`; `k:num`] V_SNSK);
    apery_lift_recurrence (SPECL [`n:num`; `k:num`] V_SK2)];;

let apery_target =
  `pflat2 vv n k - (qflat vv n (k+1) - qflat vv n k):real`;;

let apery_reduced =
  let expanded =
    REWRITE_CONV
     [pflat2; pflat; qflat;
      ARITH_RULE `(n+1)+1 = n+2`;
      ARITH_RULE `(n+2)+1 = n+3`;
      ARITH_RULE `(n+3)+1 = n+4`]
     apery_target in
  TRANS expanded
    (REWRITE_CONV apery_recurrences (rhs(concl expanded)));;

let apery_atoms =
  [`vv n k`; `vv (n+1) k`; `vv n (k+1)`]
and apery_zero = `&0:real`
and apery_one = `&1:real`;;

let apery_has_atom tm =
  can (find_term (fun t -> mem t apery_atoms)) tm;;

let apery_add x y =
  if x = apery_zero then y
  else if y = apery_zero then x
  else mk_binop add_tm x y
and apery_sub x y =
  if y = apery_zero then x
  else if x = apery_zero then mk_comb(neg_tm,y)
  else mk_binop sub_tm x y
and apery_neg x =
  if x = apery_zero then apery_zero else mk_comb(neg_tm,x)
and apery_mul x y =
  if x = apery_zero || y = apery_zero then apery_zero
  else if x = apery_one then y
  else if y = apery_one then x
  else mk_binop mul_tm x y;;

let apery_vec_add xs ys = map2 apery_add xs ys
and apery_vec_sub xs ys = map2 apery_sub xs ys
and apery_vec_neg xs = map apery_neg xs
and apery_vec_scale c xs = map (apery_mul c) xs;;

let rec apery_linearize tm =
  if mem tm apery_atoms then
    apery_zero ::
    map (fun a -> if tm = a then apery_one else apery_zero)
      apery_atoms
  else if not (apery_has_atom tm) then
    [tm; apery_zero; apery_zero; apery_zero]
  else if is_binop_op add_tm tm then
    let l,r = dest_binop add_tm tm in
    apery_vec_add (apery_linearize l) (apery_linearize r)
  else if is_binop_op sub_tm tm then
    let l,r = dest_binop sub_tm tm in
    apery_vec_sub (apery_linearize l) (apery_linearize r)
  else if is_comb tm && rator tm = neg_tm then
    apery_vec_neg (apery_linearize(rand tm))
  else if is_binop_op mul_tm tm then
    let l,r = dest_binop mul_tm tm in
    if not (apery_has_atom l) then
      apery_vec_scale l (apery_linearize r)
    else if not (apery_has_atom r) then
      apery_vec_scale r (apery_linearize l)
    else failwith "apery_linearize: nonlinear product"
  else failwith "apery_linearize: unsupported term";;

let apery_coeffs = apery_linearize(rhs(concl apery_reduced));;

let apery_unfold_coeff tm =
  REWRITE_CONV
    [qc00; qc10; qc01; GSYM REAL_OF_NUM_ADD] tm;;

let apery_normalize_denoms tm =
  REWRITE_CONV
    (map REAL_POLY_CONV (denom_factors tm [])) tm;;

let apery_normalize_coeff tm =
  let unfolded = apery_unfold_coeff tm in
  TRANS unfolded
    (apery_normalize_denoms(rhs(concl unfolded)));;

let apery_normalized_coeffs =
  map (fun tm -> rhs(concl(apery_normalize_coeff tm)))
    apery_coeffs;;

let rec apery_rational_summands tm =
  if not (has_div tm) then [tm]
  else if is_binop_op add_tm tm then
    let l,r = dest_binop add_tm tm in
    apery_rational_summands l @ apery_rational_summands r
  else if is_binop_op sub_tm tm then
    let l,r = dest_binop sub_tm tm in
    apery_rational_summands l @
    map apery_neg (apery_rational_summands r)
  else if is_comb tm && rator tm = neg_tm then
    map apery_neg (apery_rational_summands(rand tm))
  else if is_binop_op mul_tm tm then
    let l,r = dest_binop mul_tm tm in
    flat
      (map
        (fun x ->
          map (apery_mul x) (apery_rational_summands r))
        (apery_rational_summands l))
  else [tm];;

let apery_sum terms =
  end_itlist (fun x y -> mk_binop add_tm x y) terms;;

let rec apery_rational_leaves tm =
  if not (has_div tm) then [tm]
  else if is_binop_op add_tm tm ||
          is_binop_op sub_tm tm ||
          is_binop_op mul_tm tm then
    let op =
      if is_binop_op add_tm tm then add_tm
      else if is_binop_op sub_tm tm then sub_tm
      else mul_tm in
    let l,r = dest_binop op tm in
    apery_rational_leaves l @ apery_rational_leaves r
  else if is_comb tm && rator tm = neg_tm then
    apery_rational_leaves(rand tm)
  else [tm];;

let apery_abstract_identity leaves eq =
  let leaves =
    filter
      (fun t -> t <> apery_zero && t <> apery_one)
      (setify leaves) in
  let vars = map (fun t -> genvar(type_of t)) leaves in
  let abstract = map2 (fun t v -> v,t) leaves vars
  and concrete = map2 (fun t v -> t,v) leaves vars in
  INST concrete
    (prove(subst abstract eq,CONV_TAC REAL_RING));;

let apery_make_raw terms =
  map
    (fun tm ->
      let th = RATIONALIZE_CONV (nz_for tm) tm in
      let num,den = dest_div(rhs(concl th)) in
      th,num,den)
    terms;;

let APERY_RAT_CANCEL = prove
 (`!g n d:real. ~(g = &0)
                  ==> (g * n) / (g * d) = n / d`,
  CONV_TAC REAL_FIELD);;

let APERY_RAT_SCALE = prove
 (`!d D q n:real.
        ~(d = &0) /\ D = q * d
        ==> D * (n / d) = q * n`,
  CONV_TAC REAL_FIELD);;

let apery_prove_poly_eq l r =
  TRANS (REAL_POLY_CONV l) (SYM(REAL_POLY_CONV r));;

let apery_prove_nz_product tm =
  let nz =
    map
      (fun f -> MP (prove_factor_nz_imp f) hyp_thm)
      (factor_collect tm []) in
  PROVE_NZ nz tm;;

let rec apery_sum_theorems thms =
  match thms with
    [th] -> th
  | th::rest ->
      MK_COMB(AP_TERM add_tm th,apery_sum_theorems rest)
  | [] -> failwith "apery_sum_theorems";;

let apery_reduce_fractions raws reduced =
  map2
    (fun (rawth,raw_num,raw_den) (num,den,_,common) ->
      let num_th =
        apery_prove_poly_eq raw_num (mk_binop mul_tm common num)
      and den_th =
        apery_prove_poly_eq raw_den (mk_binop mul_tm common den) in
      let fraction_th =
        MK_COMB(AP_TERM div_tm num_th,den_th) in
      let cancel_th =
        MATCH_MP (SPECL [common; num; den] APERY_RAT_CANCEL)
          (apery_prove_nz_product common) in
      TRANS rawth (TRANS fraction_th cancel_th))
    raws reduced;;

let apery_bigd =
  `((&k - &n) pow 2 * (&n + &2) pow 3 * (&n + &3) pow 3 *
    (&k - &n - &4) pow 2 * (&k - &n - &3) pow 2 *
    (&k - &n - &2) pow 2 * (&k - &n - &1) pow 2 *
    (&k - &n + &1)):real`;;

let apery_bigd_poly = REAL_POLY_CONV apery_bigd
and apery_bigd_nz = apery_prove_nz_product apery_bigd;;

let apery_scale_fractions reduced =
  map
    (fun (num,den,cofactor,_) ->
      let decomp =
        TRANS apery_bigd_poly
          (SYM(REAL_POLY_CONV(mk_binop mul_tm cofactor den))) in
      MATCH_MP
        (SPECL [den; apery_bigd; cofactor; num]
          APERY_RAT_SCALE)
        (CONJ (apery_prove_nz_product den) decomp))
    reduced;;

let rec apery_scale_sum fractions scale_thms =
  match fractions,scale_thms with
    [fraction],[scale_th] -> scale_th
  | fraction::rest,scale_th::scale_rest ->
      let distribute =
        SPECL [apery_bigd; fraction; apery_sum rest]
          REAL_ADD_LDISTRIB in
      TRANS distribute
        (MK_COMB
          (AP_TERM add_tm scale_th,
           apery_scale_sum rest scale_rest))
  | _ -> failwith "apery_scale_sum";;

let apery_prove_coefficient coeff reduced =
  let summands = apery_rational_summands coeff in
  let collected =
    apery_abstract_identity
      (apery_rational_leaves coeff)
      (mk_eq(coeff,apery_sum summands)) in
  let reductions = apery_reduce_fractions
    (apery_make_raw summands) reduced in
  let reduced_th =
    TRANS collected (apery_sum_theorems reductions) in
  let scaled =
    apery_scale_sum
      (map (fun (num,den,_,_) -> mk_binop div_tm num den)
        reduced)
      (apery_scale_fractions reduced) in
  let scaled_zero =
    TRANS scaled (REAL_POLY_CONV(rhs(concl scaled))) in
  let coeff_scaled =
    AP_TERM (mk_comb(mul_tm,apery_bigd)) reduced_th in
  let cancel_eq =
    TRANS (TRANS coeff_scaled scaled_zero)
      (SYM(SPEC apery_bigd REAL_MUL_RZERO)) in
  MATCH_MP (SPECL [apery_bigd; coeff; apery_zero] CANCEL_LEM)
    (CONJ apery_bigd_nz cancel_eq);;

