let apery_k0_zero =
  apery_prove_coefficient
    (el 1 apery_normalized_coeffs) tri_k0_reduced
and apery_k1_zero =
  apery_prove_coefficient
    (el 2 apery_normalized_coeffs) tri_k1_reduced
and apery_k2_zero =
  apery_prove_coefficient
    (el 3 apery_normalized_coeffs) tri_k2_reduced;;

let rec apery_scalar_leaves tm =
  if mem tm apery_atoms then []
  else if not (apery_has_atom tm) then [tm]
  else if is_binop_op add_tm tm ||
          is_binop_op sub_tm tm then
    let op =
      if is_binop_op add_tm tm then add_tm else sub_tm in
    let l,r = dest_binop op tm in
    apery_scalar_leaves l @ apery_scalar_leaves r
  else if is_comb tm && rator tm = neg_tm then
    apery_scalar_leaves(rand tm)
  else if is_binop_op mul_tm tm then
    let l,r = dest_binop mul_tm tm in
    if not (apery_has_atom l) then l::apery_scalar_leaves r
    else if not (apery_has_atom r) then r::apery_scalar_leaves l
    else failwith "apery_scalar_leaves: nonlinear product"
  else failwith "apery_scalar_leaves: unsupported term";;

let apery_linear_form =
  apery_sum
    (map2
      (fun c a -> mk_binop mul_tm c a)
      (tl apery_coeffs) apery_atoms);;

let apery_reconstruction =
  apery_abstract_identity
    (apery_atoms @
     apery_scalar_leaves(rhs(concl apery_reduced)))
    (mk_eq(rhs(concl apery_reduced),apery_linear_form));;

let apery_original_zero i zero_th =
  TRANS (apery_normalize_coeff(el i apery_coeffs))
    zero_th;;

let apery_linear_form_zero =
  REWRITE_CONV
   [apery_original_zero 1 apery_k0_zero;
    apery_original_zero 2 apery_k1_zero;
    apery_original_zero 3 apery_k2_zero;
    REAL_MUL_LZERO; REAL_ADD_LID; REAL_ADD_RID]
   apery_linear_form;;

let apery_target_zero =
  TRANS apery_reduced
    (TRANS apery_reconstruction apery_linear_form_zero);;

let APERY_SUB_EQ_ZERO = prove
 (`!a b:real. a - b = &0 <=> a = b`,
  REAL_ARITH_TAC);;

let P_EQ_DELTA_Q =
  let l,r = dest_binop sub_tm apery_target in
  let eq = EQ_MP (SPECL [l;r] APERY_SUB_EQ_ZERO)
    apery_target_zero in
  GEN `n:num` (GEN `k:num` (DISCH apery_hyp eq));;

let VV_SUPPORT = prove
 (`!m k. m < k ==> vv m k = &0`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[vv; cc] THEN
  SUBGOAL_THEN `binom(m,k) = 0` SUBST1_TAC THENL
   [ASM_REWRITE_TAC[BINOM_EQ_0]; REWRITE_TAC[ARITH] THEN CONV_TAC REAL_RING]);;

let VV_ZERO_K = prove
 (`!m. vv m 0 = &0`,
  GEN_TAC THEN REWRITE_TAC[vv; ss] THEN
  REWRITE_TAC[SUM_CLAUSES_NUMSEG; ARITH] THEN REWRITE_TAC[REAL_MUL_RZERO]);;

let WW_EXT = prove
 (`!n i. i <= 4 ==> ww (n+i) = sum(0..n+4) (\j. vv (n+i) j)`,
  REPEAT STRIP_TAC THEN REWRITE_TAC[ww; GSYM vv] THEN CONV_TAC SYM_CONV THEN
  MATCH_MP_TAC SUM_SUPERSET THEN CONJ_TAC THENL
   [REWRITE_TAC[SUBSET; IN_NUMSEG] THEN ASM_ARITH_TAC;
    X_GEN_TAC `j:num` THEN REWRITE_TAC[IN_NUMSEG] THEN STRIP_TAC THEN
    REWRITE_TAC[] THEN MATCH_MP_TAC VV_SUPPORT THEN ASM_ARITH_TAC]);;

let INTERIOR_TELE = prove
 (`!n. 3 <= n ==> sum(1..n-2) (\j. pflat2 vv n j) = qflat vv n (n-1) - qflat vv n 1`,
  REPEAT STRIP_TAC THEN
  SUBGOAL_THEN `sum(1..n-2) (\j. pflat2 vv n j) = sum(1..n-2)(\j. qflat vv n (j+1) - qflat vv n j)` SUBST1_TAC THENL
   [MATCH_MP_TAC SUM_EQ_NUMSEG THEN REPEAT STRIP_TAC THEN REWRITE_TAC[] THEN
    MATCH_MP_TAC P_EQ_DELTA_Q THEN ASM_ARITH_TAC; ALL_TAC] THEN
  ONCE_REWRITE_TAC[REAL_ARITH `a - b = --(b - a)`] THEN
  REWRITE_TAC[SUM_NEG; SUM_DIFFS] THEN
  SUBGOAL_THEN `1 <= n - 2` ASSUME_TAC THENL [ASM_ARITH_TAC; ALL_TAC] THEN
  ASM_REWRITE_TAC[] THEN
  SUBGOAL_THEN `(n-2)+1 = n-1` SUBST1_TAC THENL [ASM_ARITH_TAC; ALL_TAC] THEN
  REAL_ARITH_TAC);;

let PFLAT_WW_DECOMP = prove
 (`!n. pflat ww n = sum(0..n+4) (\j. pflat2 vv n j)`,
  GEN_TAC THEN
  REWRITE_TAC[pflat;
    REWRITE_RULE[ADD_CLAUSES] (MP (SPECL[`n:num`;`0`] WW_EXT) (ARITH_RULE `0<=4`));
    MP (SPECL[`n:num`;`1`] WW_EXT) (ARITH_RULE `1<=4`);
    MP (SPECL[`n:num`;`2`] WW_EXT) (ARITH_RULE `2<=4`);
    MP (SPECL[`n:num`;`3`] WW_EXT) (ARITH_RULE `3<=4`);
    MP (SPECL[`n:num`;`4`] WW_EXT) (ARITH_RULE `4<=4`)] THEN
  REWRITE_TAC[GSYM SUM_LMUL] THEN REWRITE_TAC[GSYM SUM_ADD_NUMSEG] THEN
  MATCH_MP_TAC SUM_EQ_NUMSEG THEN
  REPEAT STRIP_TAC THEN
  REWRITE_TAC[pflat2; pflat] THEN REAL_ARITH_TAC);;

(* ------------------------------------------------------------------------- *)
(* The j=0 edge group, called "around_n_0" in the Coq development. Here      *)
(* qflat vv n 1 = 0 for 3 <= n. The terms vv(n+1) 1 and vv n 2 reduce via   *)
(* V_SNSK and V_SK2 at k=0 to multiples of vv n 1, while column 0 vanishes.  *)
(* ------------------------------------------------------------------------- *)

let VSNSK_K0 = prove
 (`!n. 0 < n ==> vv (n+1) 1 = (-- &n - &2 - &0) / (-- &n + &0) * vv n 1`,
  REPEAT STRIP_TAC THEN
  MP_TAC(SPECL [`n:num`; `0`] V_SNSK) THEN ASM_REWRITE_TAC[] THEN
  REWRITE_TAC[ADD_CLAUSES] THEN REWRITE_TAC[VV_ZERO_K] THEN
  REWRITE_TAC[REAL_MUL_RZERO; REAL_ADD_LID]);;

let VSK2_K0 = prove
 (`!n. 0 + 1 < n ==> vv n 2 =
      ((&n + &2 + &0) * (-- &n + &0 + &1) *
       (&2 * &0 pow 3 + &8 * &0 pow 2 + &11 * &0 + &5 - &0 * &n - &0 * &n pow 2 - &2 * &n pow 2 - &2 * &n) /
       (&0 + &2) pow 5) * vv n 1`,
  REPEAT STRIP_TAC THEN
  MP_TAC(SPECL [`n:num`; `0`] V_SK2) THEN ASM_REWRITE_TAC[] THEN
  REWRITE_TAC[ARITH_RULE `0+2 = 2`; ARITH_RULE `0+1 = 1`] THEN
  REWRITE_TAC[VV_ZERO_K] THEN
  REWRITE_TAC[REAL_MUL_RZERO; REAL_ADD_LID]);;

(* The bracket coefficient (after the two substitutions) is identically 0,
   proven by clearing the qc denominators with the certificate machinery. *)
let QFLAT_N1_BRACKET =
  let bracket_tm =
    `qc00 n 1 +
     qc10 n 1 * (-- &n - &2 - &0) / (-- &n + &0) +
     qc01 n 1 * ((&n + &2 + &0) * (-- &n + &0 + &1) *
        (&2 * &0 pow 3 + &8 * &0 pow 2 + &11 * &0 + &5 - &0 * &n - &0 * &n pow 2 - &2 * &n pow 2 - &2 * &n) /
        (&0 + &2) pow 5)` in
  let bracket_unf = rhs(concl(REWRITE_CONV[qc00;qc01;qc10] bracket_tm)) in
  let dfs = denom_factors bracket_unf [] in
  let hyp3 = ASSUME `3 <= n` in
  let prove_nz_3 f =
    prove(mk_imp(`3 <= n`, mk_neg(mk_eq(f,`&0`))),
      REWRITE_TAC[GSYM REAL_OF_NUM_LE] THEN STRIP_TAC THEN ASM_REAL_ARITH_TAC) in
  let nz3 = map (fun f -> MP (prove_nz_3 f) hyp3) dfs in
  DISCH `3 <= n` (prove_rat_eq nz3 (mk_eq(bracket_unf, `&0`)));;

let QFLAT_N1_ZERO = prove
 (`!n. 3 <= n ==> qflat vv n 1 = &0`,
  GEN_TAC THEN DISCH_TAC THEN REWRITE_TAC[qflat; ARITH_RULE `1+1 = 2`] THEN
  MP_TAC(SPEC `n:num` VSNSK_K0) THEN ANTS_TAC THENL [ASM_ARITH_TAC; ALL_TAC] THEN
  DISCH_THEN SUBST1_TAC THEN
  MP_TAC(SPEC `n:num` VSK2_K0) THEN ANTS_TAC THENL [ASM_ARITH_TAC; ALL_TAC] THEN
  DISCH_THEN SUBST1_TAC THEN
  MP_TAC QFLAT_N1_BRACKET THEN ASM_REWRITE_TAC[] THEN
  REWRITE_TAC[qc00; qc01; qc10] THEN
  CONV_TAC REAL_RING);;

let INTERIOR_FULL =
  let col0 = prove
   (`!n. pflat2 vv n 0 = &0`,
    GEN_TAC THEN REWRITE_TAC[pflat2; pflat; VV_ZERO_K] THEN REAL_ARITH_TAC) in
  prove
   (`!n. 3 <= n
         ==> sum(0..n-2) (\j. pflat2 vv n j) = qflat vv n (n-1)`,
    GEN_TAC THEN DISCH_TAC THEN
    SUBGOAL_THEN `0 <= n - 2` ASSUME_TAC THENL [ASM_ARITH_TAC; ALL_TAC] THEN
    ASM_SIMP_TAC[SUM_CLAUSES_LEFT] THEN
    REWRITE_TAC[col0] THEN
    SUBGOAL_THEN `0 + 1 = 1` SUBST1_TAC THENL [ARITH_TAC; ALL_TAC] THEN
    REWRITE_TAC[REAL_ADD_LID] THEN
    ASM_SIMP_TAC[INTERIOR_TELE] THEN
    ASM_SIMP_TAC[QFLAT_N1_ZERO] THEN REAL_ARITH_TAC);;

