(* ========================================================================= *)
(* Boundary group, called "around_p_p" in the Coq development: n=p+1, p>=1.  *)
(*   sum(p..p+5) pflat2 vv (p+1) j = -(qflat vv (p+1) p).                    *)
(* Proof by a cofactor certificate: reduce the boundary sum + qflat to 0     *)
(* modulo the cleared v-recurrences (V_*_CL), following the reduction order  *)
(* v55..v22,v51,v50,...,v21 used in theories/ops_for_b.v.                   *)
(* ========================================================================= *)

(* 6-term numseg expansion. *)
let SUM_6 = prove
 (`!f m. sum(m..m+5) f = f m + f(m+1) + f(m+2) + f(m+3) + f(m+4) + f(m+5)`,
  REPEAT GEN_TAC THEN
  SIMP_TAC([SUM_CLAUSES_LEFT;
    ARITH_RULE `m<=m+5`; ARITH_RULE `m+1<=m+5`; ARITH_RULE `m+2<=m+5`;
    ARITH_RULE `m+3<=m+5`; ARITH_RULE `m+4<=m+5`] @
    (CONJUNCTS o ARITH_RULE)
     `((m+1)+1 = m+2) /\ ((m+2)+1 = m+3) /\ ((m+3)+1 = m+4) /\ ((m+4)+1 = m+5) /\
      ((m+1)+2 = m+3) /\ ((m+1)+3 = m+4) /\ ((m+1)+4 = m+5) /\
      ((m+2)+2 = m+4) /\ ((m+2)+3 = m+5) /\ ((m+3)+2 = m+5)`) THEN
  REWRITE_TAC[SUM_SING_NUMSEG] THEN REAL_ARITH_TAC);;

let hyp1p = ASSUME `1 <= p`;;

(* support-zero rules vv(p+i)(p+t)=0 for i<t *)
let supp_rules =
  let mk_supp i t =
    let th = SPECL [mk_comb(mk_comb(`(+):num->num->num`,`p:num`),mk_small_numeral i);
                    mk_comb(mk_comb(`(+):num->num->num`,`p:num`),mk_small_numeral t)] VV_SUPPORT in
    MP th (prove(fst(dest_imp(concl th)), ARITH_TAC)) in
  map (fun (i,t) -> mk_supp i t)
    [(1,2);(1,3);(1,4);(1,5);(2,3);(2,4);(2,5);(3,4);(3,5);(4,5)];;

(* generic index normalization (p+a)+b = p+(a+b) for the boundary range *)
let GIDX = (CONJUNCTS o ARITH_RULE)
  `((p+0)+0 = p+0) /\ ((p+0)+1 = p+1) /\ ((p+0)+2 = p+2) /\
   ((p+1)+0 = p+1) /\ ((p+1)+1 = p+2) /\ ((p+1)+2 = p+3) /\
   ((p+2)+0 = p+2) /\ ((p+2)+1 = p+3) /\ ((p+2)+2 = p+4) /\
   ((p+3)+0 = p+3) /\ ((p+3)+1 = p+4) /\ ((p+3)+2 = p+5) /\
   ((p+4)+1 = p+5) /\ (p+0 = p)`;;

(* Instantiate a cleared recurrence at (p+No,p+Ko) and normalize indices. *)
let bdry_cl_inst clG no ko =
  let inst = SPECL [mk_comb(mk_comb(`(+):num->num->num`,`p:num`),mk_small_numeral no);
                    mk_comb(mk_comb(`(+):num->num->num`,`p:num`),mk_small_numeral ko)] clG in
  let pre = fst(dest_imp(concl inst)) in
  let preth = MP (prove(mk_imp(`1<=p`,pre), DISCH_TAC THEN ASM_ARITH_TAC)) hyp1p in
  REWRITE_RULE (GIDX @ [GSYM REAL_OF_NUM_ADD]) (MP inst preth);;

(* Derive each generator equation from its cleared recurrence. *)
let prove_bdry_gen_zero2 clG no ko gen_tm =
  prove(mk_imp(`1 <= p`, mk_eq(gen_tm, `&0`)),
    DISCH_TAC THEN MP_TAC(bdry_cl_inst clG no ko) THEN ASM_REWRITE_TAC[] THEN
    CONV_TAC REAL_RING);;

(* Cleared recurrences and offsets in the order used by the certificate. *)
let gen_specs = [
  (V_SK2_CL_G, 5, 3); (V_SK2_CL_G, 5, 2); (V_SK2_CL_G, 5, 1); (V_SK2_CL_G, 5, 0);
  (V_SK2_CL_G, 4, 2); (V_SK2_CL_G, 4, 1); (V_SK2_CL_G, 4, 0);
  (V_SK2_CL_G, 3, 1); (V_SK2_CL_G, 3, 0); (V_SK2_CL_G, 2, 0);
  (V_SNSK_CL_G, 4, 0); (V_SN2_CL_G, 3, 0); (V_SNSK_CL_G, 3, 0); (V_SN2_CL_G, 2, 0);
  (V_SNSK_CL_G, 2, 0); (V_SN2_CL_G, 1, 0); (V_SNSK_CL_G, 1, 0) ];;

let gen_tms = [bdry_gen0_tm;bdry_gen1_tm;bdry_gen2_tm;bdry_gen3_tm;bdry_gen4_tm;
  bdry_gen5_tm;bdry_gen6_tm;bdry_gen7_tm;bdry_gen8_tm;bdry_gen9_tm;bdry_gen10_tm;
  bdry_gen11_tm;bdry_gen12_tm;bdry_gen13_tm;bdry_gen14_tm;bdry_gen15_tm;bdry_gen16_tm];;
let cof_tms = [bdry_cof0_tm;bdry_cof1_tm;bdry_cof2_tm;bdry_cof3_tm;bdry_cof4_tm;
  bdry_cof5_tm;bdry_cof6_tm;bdry_cof7_tm;bdry_cof8_tm;bdry_cof9_tm;bdry_cof10_tm;
  bdry_cof11_tm;bdry_cof12_tm;bdry_cof13_tm;bdry_cof14_tm;bdry_cof15_tm;bdry_cof16_tm];;

let bdry_gz =
  map2
    (fun (clG,no,ko) gt -> prove_bdry_gen_zero2 clG no ko gt)
    gen_specs gen_tms;;

(* cofactor certificate: bdry_target_tm = sum cof_i*gen_i (REAL_POLY_CONV) *)
let bdry_cert_eq =
  let cert_rhs = end_itlist (fun a b -> mk_binop add_tm a b)
    (map2 (fun c g -> mk_binop mul_tm c g) cof_tms gen_tms) in
  prove(mk_eq(bdry_target_tm, cert_rhs),
    CONV_TAC(LAND_CONV REAL_POLY_CONV THENC RAND_CONV REAL_POLY_CONV) THEN REFL_TAC);;

let BDRY_TARGET_ZERO = prove
 (mk_imp(`1 <= p`, mk_eq(bdry_target_tm, `&0`)),
  DISCH_TAC THEN
  GEN_REWRITE_TAC LAND_CONV [bdry_cert_eq] THEN
  ASM_SIMP_TAC bdry_gz THEN
  REWRITE_TAC[REAL_MUL_RZERO; REAL_ADD_RID; REAL_ADD_LID]);;

(* boundary sum expansion (no v-rec substitution) *)
let BSUM_EXPAND = prove
 (`!p. 1 <= p ==>
     sum(p..p+5) (\j. pflat2 vv (p+1) j) =
     pflat2 vv (p+1) p + pflat2 vv (p+1) (p+1) +
     pflat2 vv (p+1) (p+2) + pflat2 vv (p+1) (p+3) +
     pflat2 vv (p+1) (p+4) + pflat2 vv (p+1) (p+5)`,
  GEN_TAC THEN DISCH_TAC THEN
  MP_TAC(ISPECL [`\j. pflat2 vv (p+1) j`; `p:num`] SUM_6) THEN
  REWRITE_TAC[] THEN
  DISCH_THEN SUBST1_TAC THEN REFL_TAC);;

(* Relate the target to the boundary sum, clearing the qc denominators. *)
let prove_pnz f =
  MP (prove(mk_imp(`1 <= p`, mk_neg(mk_eq(f,`&0`))),
       REWRITE_TAC[GSYM REAL_OF_NUM_ADD; GSYM REAL_OF_NUM_LE] THEN DISCH_TAC THEN
       CONV_TAC(RAND_CONV(LAND_CONV REAL_POLY_CONV)) THEN ASM_REAL_ARITH_TAC))
     (ASSUME `1 <= p`);;
let conn_rhs = mk_binop mul_tm bdry_Dcom_tm
   (mk_binop mul_tm bdry_BIGD_tm
      (mk_binop add_tm
        `sum(p..p+5)(\j. pflat2 vv (p+1) j)` `qflat vv (p+1) p`));;
let BDRY_CONNECT =
  prove(mk_imp(`1 <= p`, mk_eq(bdry_target_tm, conn_rhs)),
    DISCH_TAC THEN
    ASM_SIMP_TAC[BSUM_EXPAND] THEN
    REWRITE_TAC[pflat2; pflat; qflat;
      ARITH_RULE `(p+1)+1 = p+2`; ARITH_RULE `(p+1)+2 = p+3`;
      ARITH_RULE `(p+1)+3 = p+4`; ARITH_RULE `(p+1)+4 = p+5`] THEN
    REWRITE_TAC supp_rules THEN
    REWRITE_TAC[REAL_MUL_RZERO; REAL_ADD_RID; REAL_ADD_LID; REAL_MUL_LZERO] THEN
    REWRITE_TAC[qc00; qc01; qc10] THEN
    REWRITE_TAC[GSYM REAL_OF_NUM_ADD] THEN
    W(fun (asl,w) ->
       let dfs = denom_factors w [] in
       let nz = map prove_pnz dfs in
       ACCEPT_TAC(MP (DISCH `1 <= p` (prove_rat_eq nz w)) (ASSUME `1 <= p`))));;

(* Dcom, BIGD nonzero (factored forms) *)
let BDRY_DCOM_NZ = prove(mk_imp(`1 <= p`, mk_neg(mk_eq(bdry_Dcom_tm,`&0`))),
  DISCH_TAC THEN
  SUBGOAL_THEN (mk_eq(bdry_Dcom_tm,
    `(&p + &1) pow 4 * (&p + &2) pow 5 * (&p + &3) pow 2 * (&p + &4) pow 2`)) SUBST1_TAC THENL
   [CONV_TAC(LAND_CONV REAL_POLY_CONV THENC RAND_CONV REAL_POLY_CONV) THEN REFL_TAC;
    REWRITE_TAC[REAL_ENTIRE; REAL_POW_EQ_0; DE_MORGAN_THM] THEN
    REWRITE_TAC[GSYM REAL_OF_NUM_LE] THEN
    REPEAT(POP_ASSUM MP_TAC) THEN REPEAT STRIP_TAC THEN ASM_REAL_ARITH_TAC]);;
let BDRY_BIGD_NZ = prove(mk_imp(`1 <= p`, mk_neg(mk_eq(bdry_BIGD_tm,`&0`))),
  DISCH_TAC THEN
  SUBGOAL_THEN (mk_eq(bdry_BIGD_tm,
    `&3600 * (&p + &3) pow 3 * (&p + &4) pow 3`)) SUBST1_TAC THENL
   [CONV_TAC(LAND_CONV REAL_POLY_CONV THENC RAND_CONV REAL_POLY_CONV) THEN REFL_TAC;
    REWRITE_TAC[REAL_ENTIRE; REAL_POW_EQ_0; DE_MORGAN_THM] THEN
    REWRITE_TAC[GSYM REAL_OF_NUM_LE] THEN
    REPEAT(POP_ASSUM MP_TAC) THEN REPEAT STRIP_TAC THEN
    CONV_TAC REAL_RAT_REDUCE_CONV THEN ASM_REAL_ARITH_TAC]);;

let BOUNDARY = prove
 (`!p. 1 <= p
       ==> sum(p..p+5) (\j. pflat2 vv (p+1) j) =
           --(qflat vv (p+1) p)`,
  GEN_TAC THEN DISCH_TAC THEN
  MP_TAC(SPEC_ALL BDRY_CONNECT) THEN ASM_REWRITE_TAC[] THEN
  MP_TAC(SPEC_ALL BDRY_TARGET_ZERO) THEN ASM_REWRITE_TAC[] THEN
  DISCH_THEN(fun th1 -> DISCH_THEN(fun th2 -> MP_TAC(TRANS (SYM th2) th1))) THEN
  MP_TAC(SPEC_ALL BDRY_DCOM_NZ) THEN ASM_REWRITE_TAC[] THEN
  MP_TAC(SPEC_ALL BDRY_BIGD_NZ) THEN ASM_REWRITE_TAC[] THEN
  REWRITE_TAC[REAL_ENTIRE; DE_MORGAN_THM] THEN
  CONV_TAC REAL_RING);;

(* ------------------------------------------------------------------------- *)
(* Assembly for n >= 3: pflat ww n = 0.                                    *)
(*   sum(0..n+4) pflat2 = sum(0..n-2) + sum(n-1..n+4)                       *)
(*                       = qflat(n,n-1) + (-qflat(n,n-1)) = 0.              *)
(* ------------------------------------------------------------------------- *)
let PFLAT_WW_GE3 = prove
 (`!n. 3 <= n ==> pflat ww n = &0`,
  GEN_TAC THEN DISCH_TAC THEN
  REWRITE_TAC[PFLAT_WW_DECOMP] THEN
  SUBGOAL_THEN `sum(0..n+4) (\j. pflat2 vv n j) =
                sum(0..n-2) (\j. pflat2 vv n j) +
                sum(n-1..n+4) (\j. pflat2 vv n j)`
    SUBST1_TAC THENL
   [MP_TAC(ISPECL
     [`\j. pflat2 vv n j`; `0`; `n-2`; `n+4`] SUM_COMBINE_R) THEN
    ASM_SIMP_TAC[ARITH_RULE `3 <= n ==> 0 <= n-2+1 /\ (n-2)+1 = n-1`; LE_0;
                 ARITH_RULE `3 <= n ==> n-2 <= n+4`] THEN
    DISCH_THEN(fun th -> REWRITE_TAC[GSYM th]); ALL_TAC] THEN
  ASM_SIMP_TAC[INTERIOR_FULL] THEN
  SUBGOAL_THEN
   `sum(n-1..n+4) (\j. pflat2 vv n j) = --(qflat vv n (n-1))`
  SUBST1_TAC THENL
   [MP_TAC(SPEC `n-1` BOUNDARY) THEN
    ASM_SIMP_TAC[ARITH_RULE `3 <= n ==> 1 <= n-1`;
                 ARITH_RULE `3 <= n ==> (n-1)+1 = n`;
                 ARITH_RULE `3 <= n ==> (n-1)+5 = n+4`];
    ALL_TAC] THEN
  REAL_ARITH_TAC);;

(* ------------------------------------------------------------------------- *)
(* The creative-telescoping recurrence for ww.                               *)
(* ------------------------------------------------------------------------- *)
let PFLAT_WW = prove
 (`!n. pflat ww n = &0`,
  GEN_TAC THEN ASM_CASES_TAC `n < 3` THENL
   [SUBGOAL_THEN `n = 0 \/ n = 1 \/ n = 2` MP_TAC THENL
     [ASM_ARITH_TAC;
      DISCH_THEN(REPEAT_TCL DISJ_CASES_THEN SUBST1_TAC)] THEN
    REWRITE_TAC[pflat] THEN CONV_TAC NUM_REDUCE_CONV THEN
    REWRITE_TAC[ww; vv; cc; ss] THEN
    REWRITE_TAC[num_CONV `6`; num_CONV `5`; num_CONV `4`; num_CONV `3`;
                num_CONV `2`; num_CONV `1`; SUM_CLAUSES_NUMSEG] THEN
    CONV_TAC NUM_REDUCE_CONV THEN
    REWRITE_TAC[num_CONV `6`; num_CONV `5`; num_CONV `4`; num_CONV `3`;
                num_CONV `2`; num_CONV `1`; BINOM] THEN
    CONV_TAC NUM_REDUCE_CONV THEN CONV_TAC REAL_RAT_REDUCE_CONV;
    MATCH_MP_TAC PFLAT_WW_GE3 THEN ASM_ARITH_TAC]);;


(* Assemble P_flat[bb] = 0 from the aa*zz and ww parts. *)
let PFLAT_BB = prove
 (`!n. pflat bb n = &0`,
  GEN_TAC THEN
  SUBGOAL_THEN `pflat bb n = pflat (\m. aa m * zz m) n + pflat ww n`
    SUBST1_TAC THENL
   [REWRITE_TAC[pflat; BB_AS_AAZZ_WW] THEN BETA_TAC THEN REAL_ARITH_TAC;
    REWRITE_TAC[PFLAT_AAZZ; PFLAT_WW] THEN REAL_ARITH_TAC]);;

let BB_RECURRENCE = prove
 (`!n. (&n + &2) pow 3 * bb(n + 2) -
       (&2 * &n + &3) * (&17 * &n pow 2 + &51 * &n + &39) * bb(n + 1) +
       (&n + &1) pow 3 * bb(n) = &0`,
  REWRITE_TAC[GSYM lop] THEN MATCH_MP_TAC M_KERNEL_TRIVIAL THEN
  REWRITE_TAC[LOP_BB_0; LOP_BB_1] THEN
  GEN_TAC THEN MP_TAC(SPEC `n:num` PFLAT_BB) THEN
  REWRITE_TAC[MOL_FACTOR; ARITH_RULE `(n + 1) + 1 = n + 2`] THEN MESON_TAC[]);;

(* ========================================================================= *)
(* *** Part 4: asymptotic behaviour of a_n zeta(3) - b_n.                    *)
(* ========================================================================= *)

let dd = new_definition
 `dd n = aa(n) * bb(n + 1) - aa(n + 1) * bb(n)`;;

let DD_RECURRENCE = prove
 (`!n. (&n + &2) pow 3 * dd(n + 1) = (&n + &1) pow 3 * dd n`,
  GEN_TAC THEN REWRITE_TAC[dd] THEN
  MP_TAC(SPEC `n:num` AA_RECURRENCE) THEN
  MP_TAC(SPEC `n:num` BB_RECURRENCE) THEN
  REWRITE_TAC[ARITH_RULE `(n + 1) + 1 = n + 2`] THEN CONV_TAC REAL_RING);;

let DD_EXPLICIT = prove
 (`!n. dd n = &6 / (&n + &1) pow 3`,
  INDUCT_TAC THENL
   [CONV_TAC REAL_RAT_REDUCE_CONV THEN REWRITE_TAC[REAL_DIV_1];
    MP_TAC(SPEC `n:num` DD_RECURRENCE) THEN
    ASM_REWRITE_TAC[ADD1; GSYM REAL_OF_NUM_ADD] THEN CONV_TAC REAL_FIELD] THEN
  REWRITE_TAC[dd; bb; aa; cc; zz] THEN
  CONV_TAC NUM_REDUCE_CONV THEN
  REWRITE_TAC[num_CONV `1`; SUM_CLAUSES_NUMSEG] THEN
  REWRITE_TAC[BINOM] THEN CONV_TAC NUM_REDUCE_CONV THEN
  CONV_TAC REAL_RAT_REDUCE_CONV);;

(* ------------------------------------------------------------------------- *)
(* First just show a_n is increasing, even before we settle into             *)
(* the groove where we almost get a smooth exponential growth.               *)
(* ------------------------------------------------------------------------- *)

let AA_INCREASING = prove
 (`!n. aa n < aa(n + 1)`,
  GEN_TAC THEN REWRITE_TAC[aa; cc] THEN
  SIMP_TAC[SUM_CLAUSES_LEFT; ARITH_RULE `0 <= n + 1`] THEN
  REWRITE_TAC[SPEC `1` SUM_OFFSET] THEN
  REWRITE_TAC[binom] THEN CONV_TAC REAL_RAT_REDUCE_CONV THEN
  MATCH_MP_TAC(REAL_ARITH `x <= y ==> x < &1 + y`) THEN
  MATCH_MP_TAC SUM_LE_NUMSEG THEN X_GEN_TAC `k:num` THEN
  STRIP_TAC THEN REWRITE_TAC[] THEN MATCH_MP_TAC REAL_LE_MUL2 THEN
  SIMP_TAC[REAL_POW_LE; REAL_POS] THEN
  REWRITE_TAC[GSYM REAL_LE_SQUARE_ABS; REAL_ABS_NUM] THEN
  REWRITE_TAC[GSYM ADD1; binom; GSYM REAL_OF_NUM_ADD; ADD_CLAUSES] THEN
  REAL_ARITH_TAC);;

let AA_MONOTONIC = prove
 (`!m n. m <= n ==> aa m <= aa n`,
  MATCH_MP_TAC TRANSITIVE_STEPWISE_LE THEN
  SIMP_TAC[AA_INCREASING; ADD1; REAL_LT_IMP_LE] THEN REAL_ARITH_TAC);;

(* ------------------------------------------------------------------------- *)
(* Hence show that for large enough n we get exponential lower bound.        *)
(* ------------------------------------------------------------------------- *)

let AA_RECURRENCE_SCALED = prove
 (`!n. aa(n + 2) = (&2 * &n + &3) * (&17 * &n pow 2 + &51 * &n + &39) /
                   (&n + &2) pow 3 * aa(n + 1) -
                   (&n + &1) pow 3 / (&n + &2) pow 3 * aa n`,
  MP_TAC AA_RECURRENCE THEN MATCH_MP_TAC MONO_FORALL THEN
  CONV_TAC REAL_FIELD);;

let APERY_RATIO_COEFF_LIM = prove
 (`((\n. (&n + &1) pow 3 / (&n + &2) pow 3) ---> &1) sequentially`,
  REWRITE_TAC[GSYM REAL_POW_DIV] THEN
  GEN_REWRITE_TAC LAND_CONV [REAL_ARITH `&1 = (&1 - &0) pow 3`] THEN
  MATCH_MP_TAC REALLIM_POW THEN
  REWRITE_TAC[REAL_FIELD `(&n + &1) / (&n + &2) = &1 - inv(&n + &2)`] THEN
  MATCH_MP_TAC REALLIM_SUB THEN
  REWRITE_TAC[REALLIM_CONST; REALLIM_1_OVER_N_OFFSET]);;

let APERY_MAIN_COEFF_LIM = prove
 (`((\n. (&2 * &n + &3) * (&17 * &n pow 2 + &51 * &n + &39) /
         (&n + &2) pow 3) ---> &34) sequentially`,
  SUBST1_TAC(REAL_ARITH `&34 = &34 - &0`) THEN
  ONCE_REWRITE_TAC[REAL_FIELD
    `(&2 * &n + &3) * (&17 * &n pow 2 + &51 * &n + &39)  / (&n + &2) pow 3 =
     &34 - (&51 * &n pow 2 + &177 * &n + &155) / (&n + &2) pow 3`] THEN
  MATCH_MP_TAC REALLIM_SUB THEN REWRITE_TAC[REALLIM_CONST] THEN
  MATCH_MP_TAC REALLIM_NULL_COMPARISON THEN
  EXISTS_TAC `\n. &120 * inv(&n)` THEN
  SIMP_TAC[REALLIM_NULL_LMUL; REALLIM_1_OVER_N; EVENTUALLY_SEQUENTIALLY] THEN
  EXISTS_TAC `1` THEN REPEAT STRIP_TAC THEN
  ASM_SIMP_TAC[GSYM real_div; REAL_LE_RDIV_EQ; REAL_OF_NUM_LT; LE_1] THEN
  REWRITE_TAC[REAL_ABS_DIV; REAL_ABS_POW;
              REAL_ARITH `abs(&n + &2) = &n + &2`] THEN
  SIMP_TAC[real_abs; REAL_LE_ADD; REAL_LE_MUL; REAL_POW_LE; REAL_POS] THEN
  ONCE_REWRITE_TAC[REAL_ARITH `a / b * c:real = (a * c) / b`] THEN
  SIMP_TAC[REAL_LE_LDIV_EQ; REAL_POW_LT; REAL_ARITH `&0 < &n + &2`] THEN
  ONCE_REWRITE_TAC[GSYM REAL_SUB_LE] THEN
  CONV_TAC(RAND_CONV REAL_POLY_CONV) THEN
  REPEAT(MATCH_MP_TAC REAL_LE_ADD THEN CONJ_TAC) THEN
  SIMP_TAC[REAL_LE_MUL; REAL_POW_LE; REAL_POS]);;

let AA_LOWERBOUND = prove
 (`?A N. &0 < A /\ !n. N <= n ==> A * &31 pow n <= aa n`,
  MP_TAC APERY_MAIN_COEFF_LIM THEN MP_TAC APERY_RATIO_COEFF_LIM THEN
  REWRITE_TAC[IMP_IMP; REALLIM_SEQUENTIALLY; AND_FORALL_THM] THEN
  DISCH_THEN(MP_TAC o SPEC `&1`) THEN REWRITE_TAC[REAL_LT_01] THEN
  DISCH_THEN(CONJUNCTS_THEN2 (X_CHOOSE_THEN `N1:num` (LABEL_TAC "1"))
    (X_CHOOSE_THEN `N2:num` (LABEL_TAC "2"))) THEN
  MAP_EVERY EXISTS_TAC [`aa(MAX N1 N2 + 2) / &31 pow (MAX N1 N2 + 2)`;
                        `MAX N1 N2 + 2`] THEN
  SIMP_TAC[AA_POS_LT; REAL_LT_DIV; REAL_POW_LT; REAL_OF_NUM_LT; ARITH] THEN
  REWRITE_TAC[LE_EXISTS; LEFT_IMP_EXISTS_THM] THEN
  ONCE_REWRITE_TAC[SWAP_FORALL_THM] THEN REWRITE_TAC[FORALL_UNWIND_THM2] THEN
  ABBREV_TAC `N = MAX N1 N2 + 2` THEN
  SIMP_TAC[REAL_POW_ADD; REAL_MUL_ASSOC; REAL_DIV_RMUL;
           REAL_POW_LT; REAL_OF_NUM_LT; ARITH; REAL_LT_IMP_NZ] THEN
  INDUCT_TAC THEN
  REWRITE_TAC[real_pow; REAL_MUL_RID; ADD_CLAUSES; REAL_LE_REFL] THEN
  MP_TAC(SPEC `(N + d) - 1` AA_RECURRENCE_SCALED) THEN
  SUBGOAL_THEN `((N + d) - 1) + 2 = SUC(N + d) /\ ((N + d) - 1) + 1 = N + d`
   (fun th -> REWRITE_TAC[th])
  THENL [ASM_ARITH_TAC; DISCH_THEN SUBST1_TAC] THEN
  TRANS_TAC REAL_LE_TRANS `&33 * aa(N + d) - &2 * aa((N + d) - 1)` THEN
  CONJ_TAC THENL
   [ALL_TAC;
    MATCH_MP_TAC(REAL_ARITH
     `x <= y /\ z <= w ==> x - w:real <= y - z`) THEN
    CONJ_TAC THEN SIMP_TAC[REAL_LE_RMUL_EQ; AA_POS_LT; REAL_MUL_ASSOC] THENL
     [REMOVE_THEN "2" (MP_TAC o SPEC `(N + d) - 1`);
      REMOVE_THEN "1" (MP_TAC o SPEC `(N + d) - 1`)] THEN
    (ANTS_TAC THENL [ASM_ARITH_TAC; REAL_ARITH_TAC])] THEN
  MATCH_MP_TAC(REAL_ARITH
   `x <= &31 * a /\ b < a ==> x <= &33 * a - &2 * b`) THEN
  MP_TAC(SPEC `(N + d) - 1` AA_INCREASING) THEN
  SUBGOAL_THEN `(N + d) - 1 + 1 = N + d` SUBST1_TAC THENL
   [ASM_ARITH_TAC; DISCH_THEN(fun th -> REWRITE_TAC[th])] THEN
  GEN_REWRITE_TAC LAND_CONV [REAL_ARITH `a * &31 * b = &31 * a * b`] THEN
  ASM_SIMP_TAC[REAL_LE_LMUL; REAL_POS]);;

let APPROXIMATION_BOUND = prove
 (`!n. ZETA(&3) * aa n - bb n <= &6 * ZETA(&3) / aa(n + 1)`,
  GEN_TAC THEN MATCH_MP_TAC(ISPEC `sequentially` REALLIM_UBOUND) THEN
  EXISTS_TAC
    `\m. aa(n) * sum(n..m) (\k. bb(k + 1) / aa(k + 1) - bb(k) / aa(k))` THEN
  REWRITE_TAC[TRIVIAL_LIMIT_SEQUENTIALLY] THEN CONJ_TAC THENL
   [REWRITE_TAC[SUM_DIFFS_ALT] THEN
    MATCH_MP_TAC REALLIM_TRANSFORM_EVENTUALLY THEN
    EXISTS_TAC `\m. bb(m + 1) / aa(m + 1) * aa n - bb n` THEN CONJ_TAC THENL
     [REWRITE_TAC[EVENTUALLY_SEQUENTIALLY] THEN EXISTS_TAC `n:num` THEN
      SIMP_TAC[REAL_SUB_LDISTRIB; REAL_DIV_LMUL; AA_NONZERO] THEN
      REAL_ARITH_TAC;
      MATCH_MP_TAC REALLIM_SUB THEN REWRITE_TAC[REALLIM_CONST] THEN
      MATCH_MP_TAC REALLIM_RMUL THEN
      MP_TAC BB_OVER_AA_LIM THEN
      REWRITE_TAC[REALLIM_SEQUENTIALLY] THEN
      MESON_TAC[ARITH_RULE `N <= n ==> N <= n + 1`]];
    SIMP_TAC[AA_POS_LT; GSYM dd; DD_EXPLICIT; REAL_FIELD
     `&0 < a /\ &0 < a'
      ==> b' / a' - b / a = (a * b' - a' * b) / (a * a')`] THEN
    REWRITE_TAC[EVENTUALLY_SEQUENTIALLY] THEN EXISTS_TAC `n:num` THEN
    X_GEN_TAC `m:num` THEN DISCH_TAC THEN REWRITE_TAC[GSYM SUM_LMUL] THEN
    TRANS_TAC REAL_LE_TRANS
     `sum(n..m) (\k. &6 / (&k + &1) pow 3) / aa(n + 1)` THEN
    CONJ_TAC THENL
     [REWRITE_TAC[real_div; GSYM SUM_RMUL; REAL_INV_MUL] THEN
      MATCH_MP_TAC SUM_LE_NUMSEG THEN X_GEN_TAC `k:num` THEN STRIP_TAC THEN
      REWRITE_TAC[GSYM REAL_MUL_ASSOC; REAL_ARITH
       `a * &6 * inv k1 * inv ak * inv ak1 <= &6 * inv k1 * inv an1 <=>
        (a / ak * inv ak1) / k1 <= (&1 / an1) / k1`] THEN
      ASM_SIMP_TAC[REAL_LE_DIV2_EQ; REAL_POW_LT; REAL_ARITH`&0 < &k + &1`] THEN
      REWRITE_TAC[real_div] THEN MATCH_MP_TAC REAL_LE_MUL2 THEN
      SIMP_TAC[REAL_LE_MUL; REAL_LE_INV_EQ; REAL_LT_IMP_LE; AA_POS_LT] THEN
      ASM_SIMP_TAC[GSYM real_div; REAL_LE_LDIV_EQ; AA_POS_LT] THEN
      ASM_SIMP_TAC[REAL_MUL_LID; AA_MONOTONIC] THEN
      MATCH_MP_TAC REAL_LE_INV2 THEN
      ASM_SIMP_TAC[AA_MONOTONIC; AA_POS_LT; LE_ADD_RCANCEL];
      SIMP_TAC[REAL_LE_DIV2_EQ; AA_POS_LT;
               REAL_ARITH `&6 * a / b = (&6 * a) / b`] THEN
      REWRITE_TAC[real_div; SUM_LMUL] THEN
      MATCH_MP_TAC REAL_LE_LMUL THEN REWRITE_TAC[REAL_POS] THEN
      REWRITE_TAC[GSYM(SPEC `1` SUM_OFFSET); REAL_OF_NUM_ADD] THEN
      TRANS_TAC REAL_LE_TRANS `real_infsum (from 1) (\n. inv(&n pow 3))` THEN
      CONJ_TAC THENL
       [MATCH_MP_TAC REAL_PARTIAL_SUMS_LE_INFSUM_GEN THEN
        SIMP_TAC[FINITE_NUMSEG; SUBSET; IN_NUMSEG; IN_FROM] THEN
        SIMP_TAC[REAL_LE_INV_EQ; REAL_POW_LE; REAL_POS] THEN
        CONJ_TAC THENL [ARITH_TAC; MATCH_MP_TAC REAL_SUMS_SUMMABLE] THEN
        EXISTS_TAC `ZETA(&3)`;
        MATCH_MP_TAC REAL_EQ_IMP_LE THEN MATCH_MP_TAC REAL_INFSUM_UNIQUE] THEN
      MP_TAC ZZ_LIM THEN
      REWRITE_TAC[real_sums; REWRITE_RULE[GSYM FUN_EQ_THM; ETA_AX] zz;
                  FROM_INTER_NUMSEG; real_div; REAL_MUL_LID]]]);;

(* ========================================================================= *)
(* *** Part 5: b_n / a_n < zeta(3)                                           *)
(* ========================================================================= *)

let BB_OVER_AA_INCREASES = prove
 (`!n. bb n / aa n < bb (n + 1) / aa (n + 1)`,
  GEN_TAC THEN SIMP_TAC[REAL_SUB_LT; AA_POS_LT; REAL_LT_RDIV_EQ] THEN
  ONCE_REWRITE_TAC[REAL_ARITH `b / a * c:real = (b * c) / a`] THEN
  SIMP_TAC[AA_POS_LT; REAL_LT_LDIV_EQ] THEN
  ONCE_REWRITE_TAC[REAL_MUL_SYM] THEN
  ONCE_REWRITE_TAC[GSYM REAL_SUB_LT] THEN
  REWRITE_TAC[GSYM dd; DD_EXPLICIT] THEN
  MATCH_MP_TAC REAL_LT_DIV THEN CONV_TAC REAL_RAT_REDUCE_CONV THEN
  MATCH_MP_TAC REAL_POW_LT THEN REAL_ARITH_TAC);;

let BB_OVER_AA_LT_ZETA3 = prove
 (`!n. bb n / aa n < ZETA(&3)`,
  REWRITE_TAC[GSYM REAL_NOT_LE] THEN REPEAT STRIP_TAC THEN
  MP_TAC BB_OVER_AA_LIM THEN REWRITE_TAC[REALLIM_SEQUENTIALLY] THEN
  DISCH_THEN(MP_TAC o SPEC `bb(n + 1) / aa(n + 1) - bb n / aa n`) THEN
  REWRITE_TAC[REAL_SUB_LT; BB_OVER_AA_INCREASES] THEN
  DISCH_THEN(X_CHOOSE_THEN `m:num` (MP_TAC o SPEC `MAX m (n + 2)`)) THEN
  REWRITE_TAC[ARITH_RULE `m <= MAX m n`] THEN SUBGOAL_THEN
   `bb (n + 1) / aa (n + 1) < bb(MAX m (n + 2)) / aa(MAX m (n + 2))`
  MP_TAC THENL [ALL_TAC; ASM_REAL_ARITH_TAC] THEN
  MP_TAC(ARITH_RULE `n + 1 < MAX m (n + 2)`) THEN
  SPEC_TAC(`MAX m (n + 2)`,`r:num`) THEN SPEC_TAC(`n + 1`,`s:num`) THEN
  MATCH_MP_TAC TRANSITIVE_STEPWISE_LT THEN REWRITE_TAC[REAL_LT_TRANS] THEN
  REWRITE_TAC[ADD1; BB_OVER_AA_INCREASES]);;

(* ------------------------------------------------------------------------- *)
(* Hence put everything together.                                            *)
(* ------------------------------------------------------------------------- *)

let IRRATIONAL_ZETA3 = prove
 (`~rational(ZETA(&3))`,
  STRIP_TAC THEN
  SUBGOAL_THEN
   `?N. !n. N <= n
            ==> integer(&2 * &(LCM(1..n)) pow 3 * (bb n - ZETA(&3) * aa n))`
  STRIP_ASSUME_TAC THENL
   [FIRST_X_ASSUM(MP_TAC o GEN_REWRITE_RULE I [RATIONAL_ALT]) THEN
    DISCH_THEN(X_CHOOSE_THEN `p:num` MP_TAC) THEN
    MATCH_MP_TAC MONO_EXISTS THEN X_GEN_TAC `q:num` THEN STRIP_TAC THEN
    GEN_TAC THEN DISCH_TAC THEN REWRITE_TAC[REAL_SUB_LDISTRIB] THEN
    MATCH_MP_TAC INTEGER_SUB THEN REWRITE_TAC[BB_INTEGER] THEN
    MATCH_MP_TAC INTEGER_MUL THEN REWRITE_TAC[INTEGER_CLOSED] THEN
    REWRITE_TAC[REAL_ARITH `x pow 3 * y * z:real = (x * x * z) * (x * y)`] THEN
    MATCH_MP_TAC INTEGER_MUL THEN SIMP_TAC[INTEGER_CLOSED; AA_INTEGER] THEN
    ONCE_REWRITE_TAC[GSYM INTEGER_ABS] THEN
    ASM_REWRITE_TAC[REAL_ABS_MUL; REAL_ABS_NUM] THEN
    ONCE_REWRITE_TAC[REAL_ARITH `a * b / c:real = b * a / c`] THEN
    MATCH_MP_TAC INTEGER_MUL THEN REWRITE_TAC[INTEGER_CLOSED] THEN
    REWRITE_TAC[INTEGER_DIV] THEN
    DISJ2_TAC THEN MATCH_MP_TAC DIVIDES_LCM_SET THEN
    REWRITE_TAC[FINITE_NUMSEG; IN_NUMSEG] THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  SUBGOAL_THEN
   `((\n. &2 * &(LCM(1..n)) pow 3 * (bb n - ZETA(&3) * aa n)) ---> &0)
    sequentially`
  MP_TAC THENL
   [MATCH_MP_TAC REALLIM_NULL_LMUL THEN MP_TAC AA_LOWERBOUND THEN
    REWRITE_TAC[LEFT_IMP_EXISTS_THM] THEN
    MAP_EVERY X_GEN_TAC [`A:real`; `N1:num`] THEN STRIP_TAC THEN
    X_CHOOSE_TAC `N2:num` LCM_BOUND_SIMPLE THEN
    MATCH_MP_TAC REALLIM_NULL_COMPARISON THEN
    EXISTS_TAC `\n. &27 pow n * &6 * ZETA(&3) / (A * &31 pow (n + 1))` THEN
    CONJ_TAC THENL
     [ALL_TAC;
      REWRITE_TAC[real_div; REAL_INV_MUL; REAL_POW_ADD; REAL_ARITH
        `tsn * &6 * z * ia * inv t31 * inv(&31 pow 1) =
         (&6 / &31 * z * ia) * tsn / t31`] THEN
      MATCH_MP_TAC REALLIM_NULL_LMUL THEN
      REWRITE_TAC[GSYM REAL_POW_DIV; GSYM real_div] THEN
      MATCH_MP_TAC REALLIM_POWN THEN CONV_TAC REAL_RAT_REDUCE_CONV] THEN
    REWRITE_TAC[EVENTUALLY_SEQUENTIALLY] THEN EXISTS_TAC `MAX N1 N2` THEN
    REWRITE_TAC[ARITH_RULE `MAX N1 N2 <= n <=> N1 <= n /\ N2 <= n`] THEN
    X_GEN_TAC `n:num` THEN STRIP_TAC THEN
    REWRITE_TAC[REAL_ABS_MUL; REAL_ABS_POW; REAL_ABS_NUM] THEN
    MATCH_MP_TAC REAL_LE_MUL2 THEN
    SIMP_TAC[REAL_POW_LE; REAL_POS; REAL_ABS_POS] THEN CONJ_TAC THENL
     [REWRITE_TAC[REAL_ARITH `&27 = &3 pow 3`; REAL_POW_POW] THEN
      ONCE_REWRITE_TAC[MULT_SYM] THEN REWRITE_TAC[GSYM REAL_POW_POW] THEN
      MATCH_MP_TAC REAL_POW_LE2 THEN
      ASM_SIMP_TAC[REAL_OF_NUM_POW; REAL_OF_NUM_LE; LE_0; LT_IMP_LE];
      ALL_TAC] THEN
    TRANS_TAC REAL_LE_TRANS `&6 * ZETA (&3) / aa (n + 1)` THEN
    CONJ_TAC THENL
     [MATCH_MP_TAC(REAL_ARITH
       `a - b <= e /\ b < a ==> abs(b - a) <= e`) THEN
      REWRITE_TAC[APPROXIMATION_BOUND] THEN
      ASM_SIMP_TAC[GSYM REAL_LT_LDIV_EQ; AA_POS_LT; BB_OVER_AA_LT_ZETA3];
      ALL_TAC] THEN
    MATCH_MP_TAC REAL_LE_LMUL THEN REWRITE_TAC[REAL_POS; real_div] THEN
    SIMP_TAC[REAL_LE_LMUL_EQ; ZETA3_POS] THEN
    MATCH_MP_TAC REAL_LE_INV2 THEN
    ASM_SIMP_TAC[REAL_LT_MUL; REAL_POW_LT; REAL_ARITH `&0 < &31`] THEN
    FIRST_X_ASSUM MATCH_MP_TAC THEN ASM_ARITH_TAC;
    ALL_TAC] THEN
  REWRITE_TAC[REALLIM_SEQUENTIALLY] THEN DISCH_THEN(MP_TAC o SPEC `&1`) THEN
  REWRITE_TAC[REAL_LT_01] THEN DISCH_THEN(X_CHOOSE_TAC `M:num`) THEN
  SUBGOAL_THEN
   `!n. MAX M N <= n
        ==> &2 * &(LCM (1..n)) pow 3 * (bb n - ZETA (&3) * aa n) = &0`
  MP_TAC THENL
   [REWRITE_TAC[ARITH_RULE `MAX M N <= n <=> M <= n /\ N <= n`] THEN
    ASM_MESON_TAC[INTEGER_CLOSED; REAL_EQ_INTEGERS_IMP];
    ALL_TAC] THEN
  SIMP_TAC[REAL_ENTIRE; REAL_POW_EQ_0; REAL_OF_NUM_EQ; LCM_NONZERO; ARITH] THEN
  REWRITE_TAC[REAL_SUB_0] THEN
  SIMP_TAC[AA_POS_LT; REAL_FIELD `&0 < a ==> (b = z * a <=> z = b / a)`] THEN
  DISCH_THEN(fun th ->
   MP_TAC(SPEC `MAX M N` th) THEN MP_TAC(SPEC `MAX M N + 1` th)) THEN
  REWRITE_TAC[LE_REFL; LE_ADD] THEN DISCH_THEN SUBST1_TAC THEN
  MATCH_MP_TAC(REAL_ARITH `b:real < a ==> ~(a = b)`) THEN
  REWRITE_TAC[BB_OVER_AA_INCREASES]);;
